local newAfkGuard=(function()
-- One native idle subscription; unloading always releases a held mouse button.
return function(ctx,initialEnabled)
    local guard={enabled=initialEnabled~=false,running=true,busy=false,count=0,lastError=nil,lastAt=nil}
    local held=false
    local function release()
        if not held then return end
        local ok,err=pcall(ctx.Release)
        if ok then held=false else guard.lastError=tostring(err) end
    end
    function guard.handleIdle()
        if not guard.running or not guard.enabled or guard.busy then return end
        -- A failed mouse-up retains ownership so stop/disable can retry it.
        -- Never issue another mouse-down while the previous release is pending.
        if held then release();if held then return end end
        guard.busy=true
        local started=false
        local spawned,spawnError=pcall(ctx.Spawn,function()
            started=true
            local ok,err=pcall(function()
                if guard.running and guard.enabled then
                    held=true
                    ctx.Press()
                    guard.count+=1;guard.lastAt=ctx.Now();guard.lastError=nil
                    ctx.Wait(0.1)
                end
            end)
            if not ok then guard.lastError=tostring(err) end
            release()
            guard.busy=false
        end)
        if not spawned then
            guard.lastError=tostring(spawnError)
            if not started then guard.busy=false end
        end
    end
    local connection=ctx.Bind(guard.handleIdle)
    function guard.setEnabled(value)
        guard.enabled=value==true
        if not guard.enabled then release() end
    end
    function guard.stop()
        if not guard.running then release();return end
        guard.running,guard.enabled=false,false
        local ok,err=pcall(function()connection:Disconnect()end)
        if not ok then guard.lastError=tostring(err) end
        release()
    end
    function guard.snapshot()
        return {enabled=guard.enabled,count=guard.count,lastAt=guard.lastAt,lastError=guard.lastError}
    end
    return guard
end

end)()
local newGhostCycle=(function()
-- Pure round coordinator: native transport and care pause are supplied by the host.
return function(ctx,initialEnabled)
    local state={running=true,enabled=initialEnabled~=false,phase="idle",status="Yeni tur bekleniyor",
        paused=false,attempts=0,joins=0,resumes=0,generation=0}
    local nextAttempt,transporting,ownedQueue,exitRetryAt=0,false,false,0
    local transportDeadline,transportCancelled
    local function pause(reason)
        if not state.paused then ctx.Pause(reason);state.paused=true end
    end
    local function resume()
        if state.paused then ctx.Resume();state.paused=false;state.resumes+=1 end
    end
    function state.isIdle()
        -- Active rounds are not pending transports. Reload must wait only for
        -- a native Prepare call that can still finish and move the character.
        return not transporting
    end
    function state.setEnabled(value)
        state.enabled=value==true;state.generation+=1
        if not state.enabled and ownedQueue and not transporting then
            local readable,current=pcall(ctx.Read)
            if not readable then state.readError=tostring(current);return end
            if not current.active and not current.transition then
                ctx.LeaveQueue();ownedQueue=false;state.phase="exiting";exitRetryAt=0
            end
        end
    end
    function state.step()
        if not state.running then return end
        local current=ctx.Read()
        state.readError=nil
        local now=ctx.Now()
        if transporting and not transportCancelled and now>=transportDeadline then
            -- Cancel future movement, while retaining the lease until the
            -- pending native transport returns and invokes its callback.
            transportCancelled=true;state.generation+=1
            state.error="Katılım geçişi zaman aşımına uğradı."
        end
        if current.active then
            pause("Ghost Gallery · diğer otomasyonlar duraklatıldı")
            if state.phase~="playing" then state.joins+=1 end
            state.phase="playing";state.status="Turda · görevler duraklatıldı"
            ownedQueue=false
            return
        end
        if current.transition then
            pause("Mini oyun geçişi · görevler duraklatıldı")
            state.status="Tur geçişi tamamlanıyor"
            return
        end
        if state.phase=="playing" then
            state.phase="exiting";ownedQueue=false;exitRetryAt=0
            state.finishedCycle=state.cycle
        end
        if state.phase=="exiting" then
            pause("Ghost Gallery çıkışı · görevler duraklatıldı")
            state.status="Tur bitti · katılım alanından çıkılıyor"
            if transporting then state.status="Bekleyen katılım geçişi tamamlanıyor";return end
            if current.queued or current.inJoinZone then
                if now>=exitRetryAt then ctx.LeaveQueue();exitRetryAt=now+1 end
                return
            end
            state.phase="idle";resume();state.status="Tur bitti · görevler devam ediyor"
            nextAttempt=now+2
            return
        end
        if transporting then
            state.status=transportCancelled and "İptal edilen konum geçişi tamamlanıyor" or "Katılım alanına gidiliyor"
            return
        end
        if not state.enabled then
            if ownedQueue and (current.queued or current.inJoinZone) then
                state.phase="exiting";exitRetryAt=0
                state.status="Otomatik katılım kapalı · katılım alanından çıkılıyor"
                return
            end
            ownedQueue=false
            state.phase="idle";resume();state.status="Otomatik katılım kapalı";return
        end
        local timestamp=current.timestamp
        if current.queued then
            pause("Ghost Gallery sırası · görevler duraklatıldı")
            state.phase="waiting";state.status="Sırada · tur bekleniyor"
            if ownedQueue and timestamp and now>timestamp+25 and not current.loading then
                ctx.LeaveQueue();ownedQueue=false;state.phase="exiting";exitRetryAt=now+1;nextAttempt=now+10
            end
            return
        end
        if state.phase=="waiting" then state.phase="idle";resume();nextAttempt=now+1 end
        if not timestamp or timestamp<0 or current.canInvite==false then
            if state.phase=="preparing" then state.phase="idle";resume() end
            state.status="Yeni tur bekleniyor";return
        end
        if timestamp==state.finishedCycle then
            state.status="Yeni tur bekleniyor";return
        end
        local remaining=timestamp-now
        if remaining>45 or remaining< -10 then
            state.phase="idle";resume();state.status="Yeni tur bekleniyor";return
        end
        if state.cycle~=timestamp then state.cycle=timestamp;state.attempts=0 end
        if now<nextAttempt or state.attempts>=3 then return end
        pause("Ghost Gallery hazırlığı · görevler duraklatıldı")
        state.phase="preparing";state.status="Bakım işlemleri temizleniyor"
        if not ctx.Ready() then return end
        transporting=true;transportCancelled=false;transportDeadline=now+45;state.attempts+=1
        local generation=state.generation
        local completed=false
        local function done(success,reason)
            if completed then return end
            completed=true
            transporting=false
            local readable,latest=pcall(ctx.Read)
            if not readable then
                -- A transient location read must not discard a successful
                -- owned queue or resume before its physical state is known.
                state.readError=tostring(latest)
                if state.phase~="playing" and state.phase~="exiting" then
                    if success and state.enabled and generation==state.generation then
                        ownedQueue=true;state.phase="waiting"
                    else ownedQueue=false;state.phase="exiting";exitRetryAt=0 end
                end
                state.status="Katılım konumu yeniden okunacak"
                return
            end
            if generation~=state.generation or not state.enabled then
                if success then ctx.LeaveQueue() end
                ownedQueue=false
                -- A late acknowledgement must not erase an already observed
                -- active round; the native round owns the pause until exit.
                if not latest.active and not latest.transition and state.phase~="playing" and state.phase~="exiting" then
                    if latest.queued or latest.inJoinZone then state.phase="exiting";exitRetryAt=0
                    else state.phase="idle";resume() end
                    nextAttempt=ctx.Now()+5
                end
                return
            end
            if latest.active or latest.transition or state.phase=="playing" or state.phase=="exiting" then return end
            if success then
                ownedQueue=true;state.phase="waiting";state.error=nil
                state.status="Katılım alanında · tur bekleniyor"
            else
                state.error=tostring(reason);nextAttempt=ctx.Now()+5
                if latest.queued or latest.inJoinZone then
                    state.phase="exiting";exitRetryAt=0
                    state.status="Katılım doğrulanmadı · alandan çıkılıyor"
                else
                    state.phase="idle";state.status="Katılım yeniden denenecek";resume()
                end
            end
        end
        local ok,err=pcall(ctx.Prepare,done,function()
            return state.running and state.enabled and generation==state.generation
        end)
        if not ok then done(false,err) end
    end
    function state.stop()
        state.setEnabled(false)
        state.running=false
        resume()
    end
    return state
end

end)()
local createCare=function()
-- Adopt Me Companion, 2026-10-03. Standalone; no downloaded UI libraries.
-- Pet and baby care use native remotes; completion is checked against server data.
-- Toggles start OFF. Baby automation chooses the Babies team; water budget: 20 Bucks.
local newCareScheduler = (function()
-- Resource leases outlive cancellation until the worker's cleanup has finished.
-- This module has no remotes; the companion supplies native task actions.
return function(ctx)
    local scheduler = {jobs = {}, cooldown = {}, failures = {}, maxJobs = 6, peak = 0, recoveries = 0}
    local function key(row)
        -- Baby ailments belong to the local character, independently of the
        -- pet selection. A hatch/swap must not create a second baby worker or
        -- bypass the retry delay for the same baby ailment.
        local identity = row.target == "baby" and "self" or row.unique or "self"
        return row.target .. ":" .. tostring(identity) .. ":" .. tostring(row.key) ..
            ":" .. tostring(row.kind) .. ":" .. tostring(row.raw.created_timestamp)
    end
    local function compatible(a, b)
        if a.location and b.location and a.location ~= b.location then return false end
        -- A location-only task needs the entire venue, while an outdoor task
        -- needs a particular area within MainMap.
        if a.zone and b.zone and a.zone ~= b.zone then return false end
        for _, ar in ipairs(a.resources or {}) do
            for _, br in ipairs(b.resources or {}) do if ar == br then return false end end
        end
        return true
    end
    function scheduler.Count()
        local count = 0; for _ in pairs(scheduler.jobs) do count += 1 end; return count
    end
    function scheduler.Valid(job)
        return not job.cancelled and ctx.Alive() and ctx.Enabled(job.row, job.token)
    end
    function scheduler.Cancel()
        for _, job in pairs(scheduler.jobs) do job.cancelled = true end
        -- Retain all leases until Run returns, including pending server calls.
        ctx.Wake()
    end
    function scheduler.IsReserved(resource)
        for _, job in pairs(scheduler.jobs) do
            for _, used in ipairs(job.plan.resources or {}) do if used == resource then return true end end
        end
        return false
    end
    function scheduler.ReplaceReservation(job, oldResource, newResource)
        -- The furniture selected during planning may disappear while the
        -- interior loads. Acquire its replacement without yielding and without
        -- releasing the old lease unless the replacement is actually free.
        if type(job) ~= "table" or scheduler.jobs[job.id] ~= job or not scheduler.Valid(job) or type(newResource) ~= "string" then return false end
        for _, other in pairs(scheduler.jobs) do
            if other ~= job then
                for _, used in ipairs(other.plan.resources or {}) do if used == newResource then return false end end
            end
        end
        local resources = job.plan.resources or {}
        job.plan.resources = resources
        if table.find(resources, newResource) then return true end
        local oldIndex = oldResource and table.find(resources, oldResource)
        if oldIndex then resources[oldIndex] = newResource else table.insert(resources, newResource) end
        return true
    end
    function scheduler.Anchor()
        local best
        for _, job in pairs(scheduler.jobs) do
            if not job.cancelled and job.plan.location and
                (not best or job.plan.zone and not best.plan.zone or
                (job.plan.zone ~= nil) == (best.plan.zone ~= nil) and job.started < best.started) then best = job end
        end
        return best
    end
    function scheduler.Tick(rows)
        if not ctx.Alive() then return end
        local now = ctx.Now()
        for _,job in pairs(scheduler.jobs) do
            if ctx.Progress and not job.cancelled then
                local checked,progress=pcall(ctx.Progress,job.row)
                if checked and type(progress)=="number" and (job.progress==nil or progress>job.progress+0.0001) then
                    job.progress,job.lastProgress=progress,now
                end
                local timeout=job.plan.stallTimeout or 50
                if now-(job.lastProgress or job.started)>timeout then
                    job.cancelled=true;job.recovering=true
                    job.stage="İlerleme yok · temizlenip yeniden deneniyor"
                    scheduler.recoveries+=1
                    ctx.Wake()
                end
            end
        end
        local active = {}
        for _, row in ipairs(rows) do active[key(row)] = true end
        for id, untilTime in pairs(scheduler.cooldown) do
            if untilTime <= now or not active[id] and not scheduler.jobs[id] then scheduler.cooldown[id] = nil end
        end
        -- The creation timestamp is part of the identity. Retaining failure
        -- counters for completed/replaced cycles would grow this map forever
        -- during a long AFK session; active cycles keep their retry backoff.
        for id in pairs(scheduler.failures) do
            if not active[id] and not scheduler.jobs[id] then scheduler.failures[id] = nil end
        end
        for _, row in ipairs(rows) do
            local id = key(row)
            if not scheduler.jobs[id] and not scheduler.cooldown[id] and scheduler.Count() < scheduler.maxJobs then
                local ok, plan = pcall(ctx.Plan, row, scheduler)
                if ok and plan then
                    local permitted = true
                    for _, running in pairs(scheduler.jobs) do
                        if not compatible(plan, running.plan) then permitted = false; break end
                    end
                    if permitted then
                        local job = {id = id, row = row, token = ctx.Token(), plan = plan,
                            started = now, stage = "Event hazırlanıyor", owned = {}}
                        if ctx.Progress then
                            local checked,progress=pcall(ctx.Progress,row)
                            if checked then job.progress=progress end
                        end
                        scheduler.jobs[id] = job
                        scheduler.peak = math.max(scheduler.peak, scheduler.Count())
                        ctx.Spawn(function()
                            local ran, result = pcall(ctx.Run, job)
                            if not ran then result = {status = "failed", error = tostring(result)} end
                            result = result or {status = "failed", error = "Görev sonucu alınamadı."}
                            if job.recovering and ctx.Token()==job.token and ctx.Alive() then result.status="retry";result.error="İlerleme durdu; görev otomatik yeniden başlatılıyor."
                            elseif not scheduler.Valid(job) then result.status = "cancelled" end
                            if result.status=="failed" then scheduler.failures[id]=math.min((scheduler.failures[id] or 0)+1,4)
                            else scheduler.failures[id]=nil end
                            scheduler.cooldown[id] = ctx.Now() + (result.status == "failed" and math.min(30,3*2^(scheduler.failures[id]-1)) or 3)
                            job.result = result
                            scheduler.jobs[id] = nil
                            ctx.Record(job, result)
                            ctx.Wake()
                        end)
                    end
                elseif not ok then
                    scheduler.cooldown[id] = now + 15
                    ctx.Record({row = row}, {status = "failed", error = tostring(plan)})
                end
            end
        end
    end
    function scheduler.Snapshot()
        local out = {}
        for _, job in pairs(scheduler.jobs) do
            table.insert(out, {target = job.row.target, key = job.row.key, kind = job.row.kind,
                stage = job.stage, started = job.started, location = job.plan.location,
                cancelled = job.cancelled == true, mode = job.plan.mode, zone = job.plan.zone,
                resources = table.clone(job.plan.resources or {}), ready = job.plan.ready})
        end
        table.sort(out, function(a, b) return a.started == b.started and a.target < b.target or a.started < b.started end)
        return out
    end
    return scheduler
end

end)()
