local newStrollerSeat=(function()
-- Confirm the actual actor's seat before moving; never toggle an equipped stroller.
return function(ctx)
    local seat={attempts=0}
    function seat.Seated()
        if not ctx.Equipped() then return false end
        for _,slot in ipairs(ctx.Slots()) do if ctx.ActorSeated(slot) then return true end end
        return false
    end
    function seat.Ensure()
        for _=1,3 do
            ctx.Check()
            if not ctx.HasTask() then return false end
            if seat.Seated() then return true end
            if not ctx.Equipped() then
                ctx.Stage("Bebek arabası takılıyor")
                ctx.Equip()
            end
            local deadline=ctx.Now()+8
            while #ctx.Slots()==0 and ctx.Now()<deadline and ctx.HasTask() do ctx.Wait(0.2);ctx.Check() end
            if not ctx.HasTask() then return false end
            local free
            for _,slot in ipairs(ctx.Slots()) do
                if ctx.ActorSeated(slot) then return true end
                if not free and not ctx.Occupied(slot) then free=slot end
            end
            assert(free,"Bebek arabasında boş koltuk bulunamadı.")
            ctx.Check()
            if not ctx.HasTask() then return false end
            seat.attempts+=1;ctx.Stage("Pet koltuğa oturtuluyor · "..seat.attempts)
            ctx.UseSeat(free)
            deadline=ctx.Now()+6
            while not seat.Seated() and ctx.Now()<deadline and ctx.HasTask() do ctx.Wait(0.2);ctx.Check() end
            if not ctx.HasTask() then return false end
            if seat.Seated() then ctx.Stage("Pet koltukta · gezinti başlıyor");return true end
        end
        error("Oyun petin bebek arabasına oturduğunu doğrulamadı; görev yeniden denenecek.")
    end
    return seat
end

end)()
local areaRoute=(function()
-- Choose a short walking segment that stays inside every pinned task area.
return function(origin, axis, side, contains)
    local right = Vector3.new(axis.X, 0, axis.Z)
    right = right.Magnitude > 0.1 and right.Unit or Vector3.new(1, 0, 0)
    local forward = Vector3.new(-right.Z, 0, right.X)
    for _, length in ipairs({18, 12, 8}) do
        for _, direction in ipairs({right * side, forward * side, -right * side, -forward * side}) do
            local goal = origin + direction * length
            local valid = true
            for sample = 0, 8 do
                if not contains(origin:Lerp(goal, sample / 8)) then valid = false; break end
            end
            if valid then return goal end
        end
    end
end

end)()
local newSeatExit=(function()
-- Native seat exit with a bounded acknowledgement wait. No scheduler lease is
-- released until both replicated sitting state and local attachment are clear.
return function(ctx)
    local function clear(s)
        return not (s.sitting or s.connection or s.sit or s.platform or s.anchored)
    end
    return function()
        for attempt=1,3 do
            local before=ctx.Read()
            if not before.valid or before.transition then return true,"transition" end
            if clear(before) then return true end
            ctx.Stage("Bebek mobilyadan çıkıyor · "..attempt.."/3")
            pcall(ctx.NativeExit)
            -- The native helper may return early when replication has not yet
            -- registered is_sitting. Clear only this worker's owned character.
            pcall(ctx.LocalExit)
            local deadline=ctx.Now()+1.2
            local confirmations=0
            repeat
                local state=ctx.Read()
                if not state.valid or state.transition then return true,"transition" end
                if clear(state) then confirmations+=1 else confirmations=0 end
                if confirmations>=2 then return true end
                ctx.Wait(0.15)
            until ctx.Now()>=deadline
        end
        return false,"Bebek oturma durumu henüz temizlenmedi; çıkış tekrar denenecek."
    end
end

end)()
local newPetChoice=(function()
-- InventoryDB supplies isEgg; names containing 'egg' are never classification.
return function(randomIndex)
    local policy={mode="idle",unique=nil,eggCount=0,petCount=0}
    function policy.Reset()
        policy.mode,policy.unique="idle",nil
    end
    function policy.Choose(entries,selected)
        local eggs,pets,byId={},{},{}
        for _,entry in ipairs(entries) do
            if entry.unique~=nil and not byId[entry.unique] then
                byId[entry.unique]=entry
                table.insert(entry.isEgg and eggs or pets,entry)
            end
        end
        policy.eggCount,policy.petCount=#eggs,#pets
        local chosen
        if #eggs>0 then
            local current=byId[selected]
            local previous=byId[policy.unique]
            chosen=current and current.isEgg and current or previous and previous.isEgg and previous or eggs[1]
            policy.mode="egg"
        elseif #pets>0 then
            local previous=byId[policy.unique]
            chosen=policy.mode=="pet" and previous and not previous.isEgg and previous or nil
            if not chosen then
                local index=math.clamp(math.floor(randomIndex(1,#pets)),1,#pets)
                chosen=pets[index]
            end
            policy.mode="pet"
        else policy.mode="empty" end
        policy.unique=chosen and chosen.unique or nil
        return policy.unique,policy.mode
    end
    return policy
end

