local function rebuildPets()
    petList = {}
    inventoryEggCount=0
    for key, item in pairs(petInventory()) do
        local definition=InventoryDB.pets[item.kind or item.id]
        if definition then
            if definition.is_egg==true then inventoryEggCount+=1 end
            table.insert(petList, {unique = item.unique or key, item = item,isEgg=definition.is_egg==true})
        end
    end
    table.sort(petList, function(a, b)
        local an, bn = petName(a.item), petName(b.item)
        return an == bn and a.unique < b.unique or an < bn
    end)
    local found = false
    for _, entry in ipairs(petList) do
        if entry.unique == selected then found = true end
    end
    if not found then
        -- A removed/hatching pet must release its old actor/tool leases first.
        if busy or careScheduler and careScheduler.Count()>0 or preferEggs and (autoPets or autoVenues) then return end
        local equipped = Equipped.get_my_equipped_char_wrappers()
        local last = (data("last_equipped_pets") or {})[1]
        local equippedUnique=equipped[1] and equipped[1].pet_unique
        selected = equippedUnique and petInventory()[equippedUnique] and equippedUnique or nil
        if not selected and last and petInventory()[last] then selected = last end
        if not selected then selected = petList[1] and petList[1].unique end
    end
end
local function selectedItem()
    for _, entry in ipairs(petList) do
        if entry.unique == selected then return entry.item end
    end
end
local function selectedWrapper()
