local function ailments(target)
    local manager = data("ailments_manager") or {}
    local out = {}
    local source = target == "baby" and manager.baby_ailments or (manager.ailments or {})[selected]
    for key, row in pairs(source or {}) do
        local progress = tonumber(row.progress) or 0
        if (tonumber(row.rate) or 0) > 0 and (tonumber(row.rate_timestamp) or -1) > 0 then
            progress = progress + math.max(0, workspace:GetServerTimeNow() - row.rate_timestamp) * row.rate
        end
        table.insert(out, {key = key, raw = row, kind = row.kind or key,
            progress = math.clamp(progress, 0, 1), order = row.sort_order or 0,
            target = target == "baby" and "baby" or "pet", unique = selected})
    end
    table.sort(out, function(a, b)
        return a.order == b.order and tostring(a.key) < tostring(b.key) or a.order < b.order
    end)
    return out
end
