local function babySeatExit(owned, stage)
    local character=owned.babyCharacter
    local function read()
        local valid=character~=nil and character.Parent~=nil and player.Character==character
        local humanoid=valid and character:FindFirstChildOfClass("Humanoid")
        local root=valid and character:FindFirstChild("HumanoidRootPart")
        local state=valid and StateManager.get(character)
        return {valid=valid,
            transition=MinigameForcedState.is_enabled() or owned.seatDestination and locationId()~=owned.seatDestination,
            sitting=state and state.is_sitting==true,
            connection=valid and character:FindFirstChild("StateConnection")~=nil,
            sit=humanoid and (humanoid.Sit or humanoid.SeatPart~=nil),
            platform=humanoid and humanoid.PlatformStand,
            anchored=root and root.Anchored}
    end
    return newSeatExit({Read=read,Now=os.clock,Wait=task.wait,Stage=stage or function()end,
        NativeExit=function()StateManager.exit_seat_states()end,
        LocalExit=function()
            local s=read();if not s.valid or s.transition then return end
            if not (s.connection or s.sit or s.platform or s.anchored) then return end
            local joint=character:FindFirstChild("StateConnection")
            if joint then joint:Destroy() end
            local humanoid=character:FindFirstChildOfClass("Humanoid")
            local root=character:FindFirstChild("HumanoidRootPart")
            if humanoid then humanoid.PlatformStand=false;humanoid.Sit=false;humanoid.Jump=true end
            if root then root.Anchored=false end
            Router.get("AdoptAPI/ExitSeatStates"):FireServer()
        end})()
end
local function releaseCare(owned)
    if not owned or owned.released then return end
    -- A cancelled furniture RPC may still activate a seat when its response arrives.
    -- Its worker retains its resource lease until the response and cleanup finish.
    if (owned.pending or 0) > 0 then return false,"Geç sunucu yanıtı bekleniyor." end
    if owned.handler then pcall(function()
        if owned.handler.get_position == owned.positionFunction then
            owned.handler.get_position = owned.originalPosition
        end
        owned.handler.is_holding_pet_button = false
        if owned.handler.petting_promise then owned.handler.petting_promise:cancel() end
        if owned.focusApp.char_wrapper and owned.focusApp.char_wrapper.char == owned.focus then
            owned.focusApp:release_focus()
        end
    end) end
    if owned.pet then
        if not owned.petExitStarted then
            owned.petExitStarted=true
            owned.petExitDone=false;owned.petExitError=nil
            owned.pending=(owned.pending or 0)+1
            task.spawn(function()
                local ok,err=pcall(function()Router.get("PetAPI/ExitFurnitureUseStates"):InvokeServer(owned.pet)end)
                owned.petExitError=not ok and tostring(err) or nil
                owned.petExitDone=true;owned.pending-=1
            end)
        end
        if not owned.petExitDone then
            if owned.exitStage then owned.exitStage("Pet çıkışı · sunucu yanıtı bekleniyor") end
            return false,"Pet çıkış isteği henüz yanıtlanmadı."
        end
        if owned.petExitError then
            owned.petExitStarted=false
            return false,owned.petExitError
        end
    end
    if owned.baby then
        local exited,exitError=babySeatExit(owned,owned.exitStage)
        if not exited then return false,exitError end
    end
    if owned.focus then pcall(function() Router.get("AdoptAPI/UnfocusPet"):FireServer(owned.focus) end) end
    if owned.performance then pcall(function()
        load("PetEntityHelper").cancel_performance(owned.entity, owned.performance)
    end) end
    if owned.tool then pcall(function() Tools.unequip(owned.tool) end) end
    if owned.walking and player.Character then
        local h = player.Character:FindFirstChildOfClass("Humanoid")
        local root = player.Character:FindFirstChild("HumanoidRootPart")
        if h and root then h:MoveTo(root.Position) end
    end
    if owned.block and occupiedBlocks[owned.block] == owned then occupiedBlocks[owned.block] = nil end
    owned.released = true
    return true
end
cancelCare = function()
