local function enabled(row, token)
    return alive and not pauseReason and not MinigameForcedState.is_enabled() and token == careEpoch and
        not (row.careJob and row.careJob.cancelled) and
        (row.target == "baby" and autoBaby or row.target == "pet" and autoPets) and
