end
local function currentTask(row)
    local manager = data("ailments_manager") or {}
    local tasks = row.target == "baby" and manager.baby_ailments or (manager.ailments or {})[row.unique]
    local current = tasks and tasks[row.key]
    -- A replacement task with the same key belongs to a new cycle.
    if current and current.kind == row.kind and current.created_timestamp == row.raw.created_timestamp then return current end
end
local function completionId(target, identity, key)
