local function pauseCare(seconds, row, token)
    local deadline = os.clock() + seconds
    repeat
        if not enabled(row, token) then return false end
        task.wait(0.15)
    until os.clock() >= deadline
    return true
end
local function checkCare(row, token)
    assert(enabled(row, token), "Otomasyon durduruldu.")
    assert(player.Character and player.Character:FindFirstChild("HumanoidRootPart"), "Karakter hazir degil.")
