local function bounded(fn, row, token, seconds, owned)
    checkCare(row, token)
    owned = owned or row.careJob and row.careJob.owned
    local done, ok, result = false, false, nil
    if owned then owned.pending = (owned.pending or 0) + 1 else actionPending+=1 end
    task.spawn(function()
        if enabled(row, token) then ok, result = pcall(fn) else result = "Otomasyon durduruldu." end
        if owned then owned.pending = owned.pending - 1 else actionPending-=1 end
        done = true
    end)
    local deadline = os.clock() + (seconds or 20)
    while not done and os.clock() < deadline and enabled(row, token) do task.wait(0.15) end
    checkCare(row, token)
    assert(done, "Sunucu yaniti zaman asimina ugradi.")
    assert(ok, tostring(result))
    return result
end
