local function nextFurnitureLocation(row, current)
    local key = careRouteKey(row)
    local route = careRoutes[key] or {visited = {}}
    careRoutes[key] = route; route.visited[current] = true
    local choices = row.kind == "sleepy" and {"School","Hospital","Nursery","housing","MainMap"} or
        row.kind == "dirty" and {"housing"} or {"MainMap","Neighborhood","housing"}
    for destination in pairs(hotspots and hotspots.ailments[row.kind] or {}) do
        if destination ~= "ManorMinigameInterior" and not table.find(choices,destination) then table.insert(choices,destination) end
    end
    for _,destination in ipairs(choices) do
        if not route.visited[destination] then route.location = destination; return destination end
    end
    route.exhausted=true;route.retryAt=os.clock()+45
    return nil
end
