        position = careStation.Position + Vector3.new(0, 3.5, 0)
    end
    player.Character:PivotTo(CFrame.new(position))
    for _, wrapper in pairs(Equipped.get_my_equipped_char_wrappers()) do
        if wrapper.pet_unique == selected then
            local entity = load("PetEntityManager").get_pet_entity(wrapper.char)
            if entity then load("PetEntityManager").mark_for_immediate_teleport(entity) end
        end
    end
    pauseCare(1, row, token)
    end, debug.traceback)
    if movementOwner == row then movementOwner = nil end
    assert(moveOK, moveError)
end
local function wrapperFor(row)
    if row.target == "baby" then return data("char_wrapper") end
    return selectedWrapper()
end
local function furnitureCare(row, token, owned, plan)
    careNavigate(plan.location, row, token)
    local function available(entry)
        local loc=Interiors.get_current_location()
        if not entry or not entry.model:IsDescendantOf(workspace) or not entry.block:IsDescendantOf(entry.model) or
            loc and loc.interior and not entry.model:IsDescendantOf(loc.interior) or occupiedBlocks[entry.block] then return false end
        local furnitureData=entry.component and entry.component.props and entry.component.props.furniture_data
        return not (furnitureData and furnitureData.occupied and furnitureData.occupied[entry.block.Name]) and
            not (furnitureData and furnitureData.respawn_at and furnitureData.respawn_at>load("LiveOpsTime").now()) and
            (badFurniture[entry.block] or 0)<=os.clock()
    end
    local entry=available(plan.furniture) and plan.furniture or findFurniture(row.kind,row.target,careScheduler)
    if not entry or not entry.unique then
        local fallback = nextFurnitureLocation(row,plan.location)
        if fallback and fallback ~= plan.location then
            error({retryLocation = fallback, message = "Mobilya eksik; uygun konuma gidilecek: " .. fallback})
        end
        error("Bu gorev icin kullanilabilir mobilya bulunamadi: " .. row.kind)
    end
    local resource="block:"..tostring(entry.unique)..":"..entry.block.Name
    assert(careScheduler.ReplaceReservation(plan.job,plan.blockResource,resource),"Mobilya başka bir görev için ayrıldı; yeniden denenecek.")
    plan.furniture,plan.blockResource=entry,resource
    plan.job.plan.stallTimeout=math.max(50,entry.duration+20)
    occupiedBlocks[entry.block] = owned; owned.block = entry.block
    local wrapper = assert(wrapperFor(row), "Bakim karakteri bulunamadi.")
    if not plan.atStation then moveNear(entry.block.Position + Vector3.new(0, 3, 3), row, token) end
    plan.ready = true
    local loc = Interiors.get_current_location()
    local payload = entry.behavior.client_get_data_for_server_use and
        entry.behavior.client_get_data_for_server_use(entry.furnitureData or entry.config, entry.unique, entry.model,
            loc.house_owner, entry.block, entry.component, wrapper, wrapper.char)
    if entry.behavior.client_get_data_for_server_use then assert(payload, "Mobilya kullanim verisi alinamadi.") end
    if row.target == "baby" then
        owned.baby,owned.babyCharacter,owned.seatDestination=true,wrapper.char,plan.location
        lastBabySeatCharacter,lastBabySeatAt=wrapper.char,os.clock()
    else owned.pet = row.unique end
    local finished, requestError = false, nil
    owned.pending = (owned.pending or 0) + 1
    task.spawn(function()
        if enabled(row, token) then
            local ok, err = pcall(function()
                if loc.house_owner then
                    Router.get("HousingAPI/ActivateFurniture"):InvokeServer(loc.house_owner,
                        entry.unique, entry.block.Name, payload, wrapper.char)
                else
                    Router.get("HousingAPI/ActivateInteriorFurniture"):InvokeServer(
                        entry.unique, entry.block.Name, payload, wrapper.char)
                end
            end)
            if not ok then requestError = tostring(err) end
        end
        owned.pending = owned.pending - 1
        finished = true
    end)
    plan.job.stage = "Mobilya event'i / sunucu ilerlemesi"
    local deadline = os.clock() + entry.duration + 15
    local startedRate = false
    while enabled(row, token) and currentTask(row) and os.clock() < deadline do
        local cur = currentTask(row)
        if cur and (cur.rate or 0) > 0 then startedRate = true end
        if requestError then error(requestError) end
        if finished and not startedRate and deadline - os.clock() < entry.duration + 10 then
            badFurniture[entry.block] = os.clock() + 30
            error({retryLocation = plan.location, message = "Bu mobilya ilerleme başlatmadı; farklı mobilya deneniyor."})
        end
        task.wait(0.3)
    end
    checkCare(row, token)
    assert(not currentTask(row), "Mobilyada gorev tamamlanmadi.")
end
local function findFood(kind, target)
    local best
    for _, item in pairs((data("inventory") or {}).food or {}) do
        local def = InventoryDB.food[item.kind or item.id]
        if def and def.ailment_to_boost == kind and def.tool == "GenericTool" and
            (target == "pet" or not def.cannot_feed_to_self) and not (item.properties or {}).locked then
            if not best or (def.cost or 0) < (InventoryDB.food[best.kind or best.id].cost or 0) then best = item end
        end
    end
    return best
end
local foodKinds = {hungry = "teachers_apple", sick = "healing_apple", thirsty = "water"}
local foodVenues = {hungry = "School", sick = "Hospital", thirsty = "Supermarket"}
observeFoodPurchases=function()
    local inventory=(data("inventory") or {}).food or {}
    -- A reply can arrive before its inventory packet, or after cancellation.
    -- Keep the receipt across both cases and across script reloads.
    for kind,receipt in pairs(foodLedger.pending) do
        if receipt.sent then
            for identity,food in pairs(inventory) do
                if not receipt.before[identity] and not foodLedger.claimed[identity] and (food.kind or food.id)==kind then
                    foodLedger.spent+=receipt.cost
                    foodLedger.claimed[identity]=true
                    foodLedger.pending[kind]=nil
                    break
                end
            end
        end
    end
    for identity in pairs(foodLedger.claimed) do
        if not inventory[identity] then foodLedger.claimed[identity]=nil end
    end
    waterSpent=foodLedger.spent
end
local function reservedFoodBudget()
    local amount,count=0,0
    for _,receipt in pairs(foodLedger.pending) do amount+=receipt.cost;count+=1 end
    return amount,count
end
local function obtainFood(row, token)
    observeFoodPurchases()
    local item = findFood(row.kind, row.target)
    if item then return item end
    local kind = foodKinds[row.kind]
    local cost = InventoryDB.food[kind].cost or 0
    assert(not foodLedger.pending[kind],"Önceki yiyecek/su satın alımının envanter bildirimi bekleniyor; tekrar satın alınmayacak.")
    assert(cost<=0 or waterSpent + reservedFoodBudget() + cost <= waterBudget, "Su bütçesi doldu ("..waterBudget.." Bucks); farm menüsünden limiti artırabilirsin.")
    assert((data("money") or 0) >= cost, "Yiyecek/su icin yeterli Bucks yok.")
    if row.careJob and row.careJob.plan.location == foodVenues[row.kind] then careNavigate(foodVenues[row.kind], row, token) end
    observeFoodPurchases()
    item=findFood(row.kind,row.target)
    if item then return item end
    local before={}
    for identity in pairs((data("inventory") or {}).food or {}) do before[identity]=true end
    local receipt={kind=kind,cost=cost,before=before,started=os.clock(),sent=false}
    foodLedger.pending[kind]=receipt
    local requested,requestError=pcall(function()
        return bounded(function()
            receipt.sent=true
            local result=Router.get("ShopAPI/BuyItem"):InvokeServer("food",kind,{buy_count=1})
            if result==false or type(result)=="table" and result.success==false then
                if foodLedger.pending[kind]==receipt then foodLedger.pending[kind]=nil end
                error("Sunucu yiyecek/su satın alımını reddetti.")
            end
            observeFoodPurchases()
            return result
        end,row,token)
    end)
    if not requested then
        if not receipt.sent and foodLedger.pending[kind]==receipt then foodLedger.pending[kind]=nil end
        error(requestError)
    end
    local deadline = os.clock() + 5
    repeat
        checkCare(row, token)
        observeFoodPurchases()
        item = findFood(row.kind, row.target)
        if item then return item end
        task.wait(0.15)
    until os.clock() > deadline
    error("Yiyecek/su envantere gelmedi.")
end
local function babyFood(row, token, owned)
    for _ = 1, 10 do
        if not currentTask(row) then return end
        local item = obtainFood(row, token)
        owned.tool = item
        bounded(function() return Tools.equip(item) end, row, token)
        local deadline, tool = os.clock() + 8, nil
        repeat
            checkCare(row, token)
            tool = load("UIManager").apps.ToolApp.active_tools[item.unique]
            task.wait(0.2)
        until tool and tool.tool or os.clock() > deadline
        assert(tool and tool.tool, "Yiyecek araci hazir degil.")
        -- The user's selected action is Feed Me; keep the native START/END + animation path.
        load("ToolDBHelper").has_prompted_feed_choice[tool] = true
        bounded(function() tool:use("UIButton") end, row, token, 15)
        pauseCare(1, row, token)
    end
    assert(not currentTask(row), "Yiyecek kullanimi gorevi tamamlamadi.")
end
local function petFood(row, token, owned)
    for _ = 1, 10 do
        if not currentTask(row) then return end
        local item = obtainFood(row, token)
        local wrapper = assert(selectedWrapper(), "Pet takili degil.")
        local entity=load("PetEntityManager").get_pet_entity(wrapper.char)
        local name=load("PetPerformanceName").Eat
        if entity then owned.entity,owned.performance=entity,name end
        local accepted = bounded(function()
            return load("PetActions").feed_pet(wrapper, {item = item,
                spawn_cframe = wrapper.char:GetPivot() * CFrame.new(0, 1, -2) *
                    CFrame.fromAxisAngle(Vector3.new(1, 0, 0), math.pi / 2)})
        end, row, token)
        assert(accepted, "Native pet besleme kullanimi kabul edilmedi.")
        -- The game's Eat performance emits ConsumeFoodObject after its animation.
        -- A packet acknowledgement is not an ailment completion.
        local began, deadline, sawEat = os.clock(), os.clock() + 14, false
        while enabled(row,token) and currentTask(row) and os.clock()<deadline do
            local eating = entity and load("PetEntityHelper").has_performance(entity,name)
            if eating then sawEat = true end
            if sawEat and not eating then break end
            -- Eating is normally 4.3 seconds, plus at most six seconds approach.
            if not sawEat and os.clock()-began>11 then error("Pet yeme/içme animasyonu başlamadı.") end
            task.wait(0.15)
        end
        checkCare(row,token)
        if not currentTask(row) then return end
        assert(sawEat and not load("PetEntityHelper").has_performance(entity,name), "Pet besleme animasyonu takildi.")
        if waitTask(row,token,0.7) then return end
    end
    error("Pet besleme gorevi tamamlanmadi.")
end
local weatherTags = {rain_puddle="RainPuddleServer",snowman="SnowmanServer"}
local function weatherCare(row,token,owned,plan)
    careNavigate(plan.location,row,token)
    if weatherTags[row.kind] then
        local target,nearest = nil,math.huge
        local root = player.Character.HumanoidRootPart
        for _,model in ipairs(game:GetService("CollectionService"):GetTagged(weatherTags[row.kind])) do
            if model:IsDescendantOf(workspace) then
                local distance = (model:GetPivot().Position-root.Position).Magnitude
                if distance<nearest then target,nearest=model,distance end
            end
        end
        assert(target,"Hava durumu gorevinin alani henuz aktif degil.")
        bounded(function() Router.get("PetAPI/ExitFurnitureUseStates"):InvokeServer(row.unique) end,row,token)
        moveNear(target:GetPivot().Position+Vector3.new(0,3,0),row,token)
        plan.job.stage="Hava durumu alanı / sunucu ilerlemesi"
        assert(waitTask(row,token,30),"Hava durumu alani gorevi tamamlamadi.")
        return
    end
    local deadline=os.clock()+90
    for _=1,4 do
        if not currentTask(row) then return end
        local entry=findFurniture(row.kind,row.target)
        while not entry and os.clock()<deadline do
            checkCare(row,token)
            if not currentTask(row) then return end
            plan.job.stage="Hava durumu mobilyası / yeniden açılması bekleniyor"
            task.wait(0.4);entry=findFurniture(row.kind,row.target)
        end
        assert(entry,"Hava durumu mobilyasi mevcut konumda kullanilabilir degil.")
        local wrapper=assert(wrapperFor(row),"Pet takili degil.")
        moveNear(entry.block.Position+Vector3.new(0,3,3),row,token)
        local component=entry.component or furnitureComponent(entry.model)
        local maker=component and component.use_block_name_mapped_to_get_on_selected_callback[entry.block.Name]
        assert(maker,"Native mobilya etkileşimi hazır değil.")
        occupiedBlocks[entry.block]=owned;owned.block=entry.block;owned.pet=row.unique
        plan.job.stage="Native "..(labels[row.kind] or row.kind).." animasyonu"
        local before=(currentTask(row) or {}).progress or 0
        -- This callback starts both server and client animation. It also sends
        -- AilmentFurnitureDone when the actual animation finishes.
        bounded(maker(wrapper.char,wrapper),row,token,25)
        occupiedBlocks[entry.block]=nil;owned.block=nil
        if waitTask(row,token,0.7) then return end
        local current=currentTask(row)
        assert(current and (current.progress or 0)>before,"Native hava durumu etkileşimi ilerleme vermedi.")
        pauseCare(row.kind=="leaf_pile" and SharedConstants.leaf_pile_cooldown or SharedConstants.diving_board_cooldown,row,token)
    end
    error("Hava durumu gorevi tamamlanmadi.")
end
local function partyCare(row,token,plan)
