local worldTargets = {
    bored = {"Park", "BoredAilmentTarget"}, camping = {"Campsite", "CampsiteOrigin"},
    beach_party = {"Beach", "BeachPartyNavTarget"},
}
-- These are the real client predicates used by the native RateArea tasks.
local function areaContains(kind, position)
    local map = workspace:FindFirstChild("StaticMap")
    if not map then return false end
    if kind == "camping" then
        local camp = map:FindFirstChild("Campsite")
        local origin = camp and camp:FindFirstChild("CampsiteOrigin")
        return origin and (origin.Position-position).Magnitude < 100 or false
    elseif kind == "bored" then
        local park = map:FindFirstChild("Park")
        local target = park and park:FindFirstChild("AilmentTarget")
        if not target or position.Y <= target.Position.Y or position.Y >= target.Position.Y+170 then return false end
        local utilities = load("Utilities")
        return utilities.point_in_points(position, {utilities.get_corners(target)})
    elseif kind == "beach_party" then
        local beach = map:FindFirstChild("Beach")
        local target = beach and beach:FindFirstChild("BeachPartyAilmentTarget")
        local perimeter = beach and beach:FindFirstChild("BeachPartyAilmentPerimeter")
        if not target or not perimeter or position.Y <= target.Position.Y-20 or position.Y >= target.Position.Y+170 then return false end
        return load("Utilities").point_in_points(position, {}, perimeter)
    end
    return false
end
local function waitAnchor(row, token, plan)
    local anchor = plan.anchor
    if not anchor then return end
    local deadline = os.clock()+35
    while not anchor.plan.ready do
        checkCare(row, token)
        assert(not anchor.cancelled and not anchor.result, "Ortak görev alanına ulaşma başarısız; yeniden planlanacak.")
        assert(os.clock()<deadline, "Ortak görev alanı yüklenemedi.")
        if plan.job then plan.job.stage="Ortak görev alanına ulaşılması bekleniyor" end
        task.wait(0.1)
    end
    assert(locationId()==plan.location, "Ortak görev konumu değişti; yeniden planlanacak.")
end
local function outdoorCare(row, token)
    local plan = row.careJob.plan
    if plan.anchor then
        waitAnchor(row, token, plan)
        plan.ready = true
        assert(waitTask(row, token, 85), "Alan görevi sunucuda tamamlanmadı.")
        return
    end
    careNavigate("MainMap", row, token)
    local target
    if row.kind == "toilet" then
        local root = player.Character.HumanoidRootPart
        local distance = math.huge
        for _, candidate in ipairs(game:GetService("CollectionService"):GetTagged("FireHydrantServer")) do
            if candidate:IsDescendantOf(workspace) then
                local d = (candidate:GetPivot().Position - root.Position).Magnitude
                if d < distance then distance, target = d, candidate end
            end
        end
    else
        target = workspace:FindFirstChild("StaticMap")
        for _, name in ipairs(worldTargets[row.kind]) do target = target and target:FindFirstChild(name) end
    end
    assert(target, "Gorev alani henuz yuklenmedi.")
    moveNear(target:GetPivot().Position + Vector3.new(0, 3, 0), row, token)
    plan.ready = true
    assert(waitTask(row, token, row.kind == "toilet" and 25 or 85), "Alan gorevi sunucuda tamamlanmadi.")
end
local function movementCare(row, token, owned)
    local plan = row.careJob.plan
    careNavigate("MainMap", row, token)
    bounded(function() Router.get("PetAPI/ExitFurnitureUseStates"):InvokeServer(row.unique) end,row,token)
    local rideSeat
    if row.kind == "ride" then
        local inventory=(data("inventory") or {}).strollers or {}
        local stroller
        for _,item in pairs(Tools.get_equipped_by_category("strollers")) do
            if inventory[item.unique] then stroller=inventory[item.unique];break end
        end
        if not stroller then
            local choices={}
            for _,item in pairs(inventory) do table.insert(choices,item) end
            table.sort(choices,function(a,b)
                local ad,bd=(a.kind or a.id)=="stroller-default",(b.kind or b.id)=="stroller-default"
                if ad~=bd then return ad end
                return tostring(a.unique)<tostring(b.unique)
            end)
            stroller=choices[1]
        end
        assert(stroller, "Gezinti icin envanterinde bebek arabasi gerekli.")
        local wrapper = assert(selectedWrapper(), "Pet takili degil.")
        owned.tool, owned.pet = stroller, row.unique
        local function slots()
            local handler=load("UIManager").apps.ToolApp.active_tools[stroller.unique]
            local tool=handler and handler.tool
            local model=tool and tool:FindFirstChild("ModelHandle")
            local touch=model and model:FindFirstChild("TouchToSits")
            return touch and touch:GetChildren() or {}
        end
        local function weld(slot)
            return (slot:FindFirstChild("SitPos") or slot):FindFirstChild("SeatWeld")
        end
        rideSeat=newStrollerSeat({Now=os.clock,Check=function()checkCare(row,token)end,
            HasTask=function()return currentTask(row)~=nil end,
            Wait=function(seconds)pauseCare(seconds,row,token)end,
            Stage=function(text)if row.careJob then row.careJob.stage=text end end,
            Equipped=function()return Tools.is_equipped(stroller)end,Slots=slots,
            ActorSeated=function(slot)
                local joint=weld(slot)
                if not joint or not (joint:IsA("JointInstance") or joint:IsA("WeldConstraint")) then return false end
                return (joint.Part0 and joint.Part0:IsDescendantOf(wrapper.char)) or
                    (joint.Part1 and joint.Part1:IsDescendantOf(wrapper.char)) or false
            end,
            Occupied=function(slot)return weld(slot)~=nil end,
            Equip=function()
                bounded(function()
                    local accepted,reason=Tools.equip(stroller,{chars_to_sit={wrapper}})
                    assert(accepted,type(reason)=="table" and reason.message or "Bebek arabası takılamadı.")
                end,row,token)
            end,
            UseSeat=function(slot)
                bounded(function()return Router.get("AdoptAPI/UseStroller"):InvokeServer(player,wrapper.char,slot)end,row,token)
            end})
        rideSeat.Ensure()
        if not currentTask(row) then return end
    end
    local root, humanoid = player.Character.HumanoidRootPart, player.Character:FindFirstChildOfClass("Humanoid")
    assert(humanoid, "Yurume karakteri bulunamadi.")
    plan.ready = true
    local start, deadline, side, nextTurn = root.Position, os.clock() + 110, 1, 0
    local lastPosition,lastMoved,lastProgress = root.Position,os.clock(),os.clock()
    local progress=(currentTask(row) or {}).progress or 0
    local axis=root.CFrame.RightVector*Vector3.new(1,0,1)
    if axis.Magnitude<0.1 then axis=Vector3.new(1,0,0) else axis=axis.Unit end
    owned.walking = true
    while enabled(row, token) and currentTask(row) and os.clock() < deadline do
        if rideSeat and not rideSeat.Seated() then
            humanoid:MoveTo(root.Position)
            rideSeat.Ensure()
            if not currentTask(row) then break end
            lastProgress,nextTurn=os.clock(),0
        end
        if os.clock() >= nextTurn then
            local goal
            if worldTargets[plan.zone] then
                goal = areaRoute(root.Position, axis, side, function(position) return areaContains(plan.zone, position) end)
                assert(goal, "Görev alanı içinde yürünebilir rota bulunamadı; yeniden deneniyor.")
            else goal = start + axis * side * 22 end
            humanoid:MoveTo(goal)
            side, nextTurn = -side, os.clock() + 2.8
        end
        if (root.Position-lastPosition).Magnitude>1 then lastPosition,lastMoved=root.Position,os.clock() end
        local current=currentTask(row)
        if current and (current.progress or 0)>progress then progress,lastProgress=current.progress,os.clock() end
        if os.clock()-lastMoved>3 then
            humanoid.Jump=true;axis=Vector3.new(-axis.Z,0,axis.X);start=root.Position
            nextTurn,lastMoved=0,os.clock()
        end
        assert(os.clock()-lastProgress<25,"Yuruyus ilerlemiyor; petin takip/oturma durumunu kontrol et.")
        task.wait(0.3)
    end
    checkCare(row, token)
    assert(not currentTask(row), "Yuruyus/gezinti ilerlemedi; yol veya oturma durumu uygun degil.")
end
local function pettingCare(row, token, owned)
