local function playCare(row, token, owned)
    local toy
    for _, item in pairs((data("inventory") or {}).toys or {}) do
        local def = InventoryDB.toys[item.kind or item.id]
        if def and def.tool == "ThrowToyTool" then toy = item; break end
    end
    assert(toy, "Oyun icin atilabilen oyuncak gerekli.")
    local helper, throws = load("ThrowToyHelper"), 0
    local deadline = os.clock() + 100
    local function stage(text)
        if row.careJob then row.careJob.stage = text end
    end
    while os.clock() < deadline and throws < 8 do
        checkCare(row, token)
        if not currentTask(row) then return end
        stage("Oyun: oyuncak hazırlanıyor")
        owned.tool = toy
        local permitted = Tools.is_equipped(toy) or bounded(function() return Tools.equip(toy) end, row, token)
        assert(permitted, "Oyun oyuncagi takilamadi.")
        if not currentTask(row) then return end
        local object = bounded(function()
            return helper.generic_throw_toy_use(toy, "UIButton", {
                reaction_name = load("PetReactionName").ThrowToyReaction, pet_unique = row.unique,
                custom_throw_function = function(model, direction)
                    -- Streaming may deliver the model before PrimaryPart is assigned.
                    local readyBy = os.clock() + 2
                    while model.Parent and not model.PrimaryPart and os.clock() < readyBy do
                        checkCare(row, token); task.wait(0.1)
                    end
                    checkCare(row, token)
                    assert(model.Parent, "Oyuncak modeli atilmadan kaldirildi.")
                    if not model.PrimaryPart then
                        local part = load("ToolHandleHelper").get_largest_part(model:GetDescendants())
                        assert(part and part:IsA("BasePart"), "Oyuncak fizik parcasi yuklenmedi.")
                        model.PrimaryPart = part
                    end
                    helper.throw(model, direction)
                end,
            })
        end, row, token)
        assert(object, "Sunucu oyuncak nesnesini olusturmadi.")
        throws += 1
        stage("Oyun: pet oyuncağı getiriyor · atış " .. tostring(throws))
        -- The native fetch performance re-equips the toy on return. Re-throw
        -- as soon as that happens; never overlap a fetch with another throw.
        local fetchStarted, returned = os.clock(), false
        local fetchBy = math.min(deadline, fetchStarted + 16)
        while os.clock() < fetchBy do
            checkCare(row, token)
            if not currentTask(row) then return end
            if os.clock() - fetchStarted >= 0.5 and
                (Tools.is_equipped(toy) or not object.Parent) then
                returned = true; break
            end
            task.wait(0.15)
        end
        checkCare(row, token)
        if not currentTask(row) then return end
        assert(returned, "Pet oyuncagi geri getirmedi; konum veya yol engeli olabilir.")
        -- Allow DropPetObject and the replicated progress to settle.
        if waitTask(row, token, 0.5) then return end
    end
    error("Oyuncak atislari sunucuda oyun gorevini tamamlamadi.")
end
local function performCare(row, token, owned, plan)
    checkCare(row, token)
    waitAnchor(row, token, plan)
    if row.target == "pet" then bounded(equip, row, token, 15) end
    local current = currentTask(row)
    if not current then return end
    if plan.mode == "observe" then
        plan.ready = true
        if row.target=="baby" and (row.kind=="sleepy" or row.kind=="dirty" or row.kind=="toilet") then
            owned.baby,owned.babyCharacter,owned.seatDestination=true,player.Character,plan.location
            lastBabySeatCharacter,lastBabySeatAt=player.Character,os.clock()
        end
        plan.job.stage = "Sunucudaki mevcut ilerleme izleniyor"
        assert(waitTask(row, token, 100), "Sunucudaki gorev ilerlemesi zaman asimina ugradi.")
        return
    end
    if venues[row.kind] then
        plan.job.stage = "Konum event'i / sunucu ilerlemesi"
        careNavigate(venues[row.kind], row, token)
        plan.ready = true
        assert(waitTask(row, token, 85), "Konum gorevi tamamlanmadi.")
    elseif plan.mode == "food" then
        plan.job.stage = "Yiyecek event'i / native kullanım"
        careNavigate(plan.location, row, token)
        plan.ready = true
        if row.target == "baby" then babyFood(row, token, owned) else petFood(row, token, owned) end
    elseif row.kind == "toilet" then
        if plan.mode == "furniture" then furnitureCare(row, token, owned, plan) else outdoorCare(row, token) end
    elseif row.kind == "hungry" or row.kind == "thirsty" or row.kind == "sleepy" or row.kind == "dirty" or row.kind == "sick" then
        furnitureCare(row, token, owned, plan)
    elseif worldTargets[row.kind] then outdoorCare(row, token)
    elseif row.kind == "pet_me" or row.kind == "play" then
        careNavigate(plan.location, row, token)
        plan.ready = true
        if row.kind == "pet_me" then pettingCare(row, token, owned) else playCare(row, token, owned) end
    elseif row.kind == "walk" or row.kind == "ride" then movementCare(row, token, owned)
    elseif row.kind == "party_zone" then partyCare(row,token,plan)
    elseif weatherTags[row.kind] or row.kind == "leaf_pile" or row.kind == "diving_board" then weatherCare(row,token,owned,plan)
    elseif row.kind == "mystery" then
        local helper = require(RS.new.modules.Ailments.Helpers.MysteryHelper)
        local action = helper.get_action(row.raw)
        local slots = action:_get_ailment_slots(wrapperFor(row))
        local rank = {hungry = 1, thirsty = 2, sleepy = 3, dirty = 4, sick = 5,
            toilet = 6, pet_me = 7, school = 8, salon = 8, pizza_party = 8, cat_cafe = 8,
            bored = 9, camping = 10, beach_party = 10, play = 11, walk = 12, ride = 13,
            rain_puddle=8,snowman=8,party_zone=8,leaf_pile=12,diving_board=12}
        local index, kind, score = nil, nil, math.huge
        for slot, candidate in pairs(slots) do
            if rank[candidate] and rank[candidate] < score then index, kind, score = slot, candidate, rank[candidate] end
        end
        assert(index and kind, "Gizem secenekleri hazir degil.")
        Router.get("AilmentsAPI/ChooseMysteryAilment"):FireServer(row.unique, action.options.ailment_key, index, kind)
        assert(waitTask(row, token, 8), "Gizem secimi sunucuda dogrulanmadi.")
    else error("Bu event gorevi henuz desteklenmiyor: " .. row.kind) end
end
local function planCare(row, scheduler)
    local actor = "actor:" .. (row.target == "pet" and tostring(row.unique) or "baby")
    local current = locationId()
    local anchor = scheduler.Anchor and scheduler.Anchor()
    local anchorPlan = anchor and anchor.plan
    local portableLocation = anchorPlan and anchorPlan.location or stationMode and stationLocation or current
    local passive = venues[row.kind] or worldTargets[row.kind] or row.kind == "party_zone"
    local plan = {location = current, resources = {}, mode = "active",
        stallTimeout=(row.kind=="leaf_pile" or row.kind=="diving_board") and 130 or 50}
    if row.kind == "at_work" then stationWaiting[row.kind]="İşten ayrılınca pet ihtiyaçları geri gelir"; return nil end
    if row.kind == "mystery" then plan.location = nil; return plan end
    if not passive then table.insert(plan.resources, actor) end
    if (row.raw.rate or 0) > 0 then
        plan.mode = "observe"
        if row.target=="baby" and (row.kind=="sleepy" or row.kind=="dirty" or row.kind=="toilet") then
            table.insert(plan.resources,"walking")
        end
        if worldTargets[row.kind] or weatherTags[row.kind] or row.kind=="party_zone" or row.kind == "toilet" and current == "MainMap" then plan.zone = row.kind end
        -- A stroller can produce both walk and ride progress. Only observe the
        -- second task after the server says it is progressing; never drive twice.
        if (row.kind=="walk" or row.kind=="ride") and anchor and
            (anchor.row.kind=="walk" or anchor.row.kind=="ride") and anchor.row.unique==row.unique then
            plan.resources = {}; plan.zone = anchorPlan.zone
        end
        plan.ready = true
        return plan
    end
    if venues[row.kind] then plan.location=venues[row.kind]
    elseif row.kind=="party_zone" then
        local party=AdminAbuse.get_value("party_zone")
        if not party then stationWaiting[row.kind]="Parti etkinliği bekleniyor";return nil end
        plan.location,plan.zone=party.destination_id,"party_zone"
    elseif weatherTags[row.kind] or row.kind=="leaf_pile" or row.kind=="diving_board" then
        if row.target=="baby" then return nil end
        plan.location=(current=="MainMap" or current=="Neighborhood") and current or "MainMap"
        plan.zone=row.kind
    elseif foodKinds[row.kind] and (row.target == "baby" or row.kind == "sick" or findFood(row.kind, row.target)) then
        plan.mode = "food"
        plan.location=findFood(row.kind,row.target) and portableLocation or foodVenues[row.kind]
        table.insert(plan.resources, "tools")
    elseif row.kind == "hungry" or row.kind == "thirsty" or row.kind == "sleepy" or row.kind == "dirty" or row.kind == "toilet" then
        local furniture = findFurniture(row.kind, row.target, scheduler)
        if not furniture and findFurniture(row.kind, row.target, nil, true) then return nil end
        if not furniture and row.kind == "toilet" then
            plan.location, plan.zone = "MainMap", "toilet"
        elseif not furniture and foodKinds[row.kind] then
            plan.mode, plan.location = "food", foodVenues[row.kind]
            table.insert(plan.resources, "tools")
        else
            plan.mode = "furniture"
            if not furniture then
                local route=careRoutes[careRouteKey(row)]
                plan.location=route and route.location or row.kind=="sleepy" and "School" or "housing"
                if route and route.exhausted then
                    if route.retryAt and os.clock()>=route.retryAt then careRoutes[careRouteKey(row)]=nil
                    else stationWaiting[row.kind]="Uygun mobilya gerekiyor; otomatik tekrar kontrol edilecek";return nil end
                end
            else
                plan.furniture=furniture
                plan.blockResource="block:" .. tostring(furniture.unique) .. ":" .. furniture.block.Name
                table.insert(plan.resources,plan.blockResource)
                if row.target=="baby" then table.insert(plan.resources,"walking") end
                if plan.location == "MainMap" then
                    if anchorPlan and worldTargets[anchorPlan.zone] and areaContains(anchorPlan.zone,furniture.block.Position+Vector3.new(0,3,3)) then
                        plan.zone = anchorPlan.zone
                    else plan.zone = "furniture:" .. tostring(furniture.unique) end
                end
            end
        end
    elseif worldTargets[row.kind] then plan.location, plan.zone = "MainMap", row.kind
    elseif row.kind == "walk" or row.kind == "ride" then
        plan.location, plan.zone = "MainMap", anchorPlan and worldTargets[anchorPlan.zone] and anchorPlan.zone or "movement"
        table.insert(plan.resources, "walking")
        if row.kind == "ride" then table.insert(plan.resources, "tools") end
    elseif row.kind == "play" then plan.location=portableLocation;table.insert(plan.resources, "tools")
    elseif row.kind == "pet_me" then plan.location=portableLocation;table.insert(plan.resources, "focus")
    else stationWaiting[row.kind]="Bu sürümde görev yolu bulunamadı";return nil end
    if anchorPlan and plan.location==anchorPlan.location then
        local portable = plan.mode=="food" or row.kind=="play" or row.kind=="pet_me"
        -- A moving/furniture/weather action is not an anchor for portable pet
        -- actions; retain its physical actor lease and do not follow its zone.
        if portable and (not anchorPlan.zone or worldTargets[anchorPlan.zone] or anchor.row.kind=="party_zone") then
            plan.zone=anchorPlan.zone;plan.stayPut=true
        end
        if (not plan.zone or plan.zone==anchorPlan.zone) and
            (venues[anchor.row.kind] or worldTargets[anchor.row.kind] or anchor.row.kind=="party_zone" or anchorPlan.ready) then
            plan.anchor=anchor
        end
    end
    plan.atStation=stationMode and plan.location==stationLocation and not plan.zone
    if row.target=="baby" and plan.mode=="furniture" and not table.find(plan.resources,"walking") then
        table.insert(plan.resources,"walking")
    end
    return plan
end
careScheduler = newCareScheduler({Alive = function() return alive end, Token = function() return careEpoch end,
    Enabled = enabled, Now = os.clock, Spawn = task.spawn, Plan = planCare,
    Progress=function(row)
        local current=currentTask(row)
        if not current then return 1 end
        local progress=tonumber(current.progress) or 0
        if (tonumber(current.rate) or 0)>0 and (tonumber(current.rate_timestamp) or 0)>0 then
            progress+=math.max(0,workspace:GetServerTimeNow()-current.rate_timestamp)*current.rate
        end
        return math.clamp(progress,0,1)
    end,
    Wake = function() if wakeCare then wakeCare() else careDirty = true end end,
    Run = function(job)
        local row, token, owned, began = job.row, job.token, job.owned, job.started
        row.careJob, job.plan.job = job, job
        local ok, err = xpcall(function() performCare(row, token, owned, job.plan) end,function(value)
            if type(value)=="table" and value.retryLocation then return value end
            return debug.traceback(tostring(value),2)
        end)
        -- Keep actor/tool/location leases while a cancelled request is outstanding.
        owned.exitStage=function(text)job.stage=text end
        local nextExit=0
        while (owned.pending or 0) > 0 do
            if os.clock()-began>35 then job.stage="Geç sunucu yanıtı · kaynaklar güvenli biçimde tutuluyor" end
            if owned.baby and os.clock()>=nextExit then
                babySeatExit(owned,owned.exitStage);nextExit=os.clock()+2
            end
            task.wait(0.1)
        end
        local function safeRelease()
            local completed,released,releaseError=pcall(releaseCare,owned)
            if not completed then return false,tostring(released) end
            return released,releaseError
        end
        local released,releaseError=safeRelease()
        while released==false do
            lastError=releaseError
            task.wait(2)
            job.stage=releaseError or "Bakım temizliği yeniden deneniyor"
            released,releaseError=safeRelease()
        end
        local cancelled = not careScheduler.Valid(job)
        if not cancelled and not ok and type(err)=="table" and err.retryLocation then
            local route=careRoutes[careRouteKey(row)] or {visited={}}
            careRoutes[careRouteKey(row)]=route;route.location=err.retryLocation
            return {status="retry",error=err.message}
        end
        if not cancelled and ok and row.kind ~= "mystery" then
            local grace = os.clock() + 2
            while enabled(row, token) and os.clock() < grace do
                local event = completionEvents[completionId(row.target, row.target == "pet" and row.unique or "self", row.key)]
                if event and event.time >= began then break end
                task.wait(0.1)
            end
        end
        cancelled = not careScheduler.Valid(job)
        local event = completionEvents[completionId(row.target, row.target == "pet" and row.unique or "self", row.key)]
        local confirmed = event ~= nil and event.time >= began
        local success = not cancelled and ok and not currentTask(row) and (confirmed or row.kind == "mystery")
        if success then careRoutes[careRouteKey(row)]=nil end
        return {status = cancelled and "cancelled" or success and (row.kind == "mystery" and "selected" or "completed") or "failed",
            serverConfirmed = confirmed == true,
            error = not ok and tostring(err):match("[^\n]+") or not success and not cancelled and
                "Gorev tamamlanma bildirimi gelmedi veya gorev halen aktif." or nil}
    end,
    Record = function(job, result)
        result.target, result.kind, result.key = job.row.target, job.row.kind, job.row.key
        table.insert(careHistory, result)
        if #careHistory > 30 then table.remove(careHistory, 1) end
        if result.status == "failed" then lastError = result.error
        elseif result.status=="completed" or result.status=="selected" then lastError=nil end
    end})
local function tickPetChoice()
    if not preferEggs or not (autoPets or autoVenues) then return false end
    if busy or pauseReason or MinigameForcedState.is_enabled() or os.clock()<actionRetryAt then return false end
    rebuildPets()
    local desired=petChoice.Choose(petList,selected)
    if desired==selected and not petHandover then return false end
    if careScheduler.Count()>0 then
        if not petHandover then cancelCare() end
        petHandover={unique=desired}
        notify("Yumurta / pet değişimi · mevcut bakım temizleniyor.")
        return true
    end
    selected,petHandover=desired,nil
    venueState=nil
    notify(desired and (petChoice.mode=="egg" and "Yumurta görevleri · doğal açılma bekleniyor." or "Yumurta kalmadı · rastgele petle devam ediliyor.") or "Envanterde yumurta veya pet bekleniyor.")
    return false
end
local function tickCare()
    if busy or not (autoPets or autoBaby) then return end
    if pauseReason then notify(pauseReason);return end
    if MinigameForcedState.is_enabled() then
        if careScheduler.Count()>0 then cancelCare() end
        notify("Mini oyun sırasında pet/bebek bakımı bekliyor.")
        return
    end
    if tickPetChoice() then return end
    -- A task from an older build or a manually entered seat may have no worker
    -- left to release it. Recover before scheduling the next baby action.
    if autoBaby and not careScheduler.IsReserved("actor:baby") then
        local character=player.Character
        local state=character and StateManager.get(character)
        local humanoid=character and character:FindFirstChildOfClass("Humanoid")
        local root=character and character:FindFirstChild("HumanoidRootPart")
        local recentSeat=character==lastBabySeatCharacter and os.clock()-lastBabySeatAt<120
        if character and (state and state.is_sitting or character:FindFirstChild("StateConnection") or
            humanoid and (humanoid.Sit or humanoid.SeatPart or recentSeat and humanoid.PlatformStand) or recentSeat and root and root.Anchored) then
            runAction(function()
                local owned={baby=true,babyCharacter=character,seatDestination=locationId()}
                local exited,exitError=babySeatExit(owned,notify)
                assert(exited,exitError)
                wakeCare()
            end)
            return
        end
    end
    if autoBaby and data("team") ~= "Babies" then
        if careScheduler.Count() > 0 then cancelCare(); return end
        local token = careEpoch
        runAction(function()
            local row = {target = "baby"}
            bounded(function() return Router.get("TeamAPI/ChooseTeam"):InvokeServer("Babies", {
                dont_respawn = true, source_for_logging = "avatar_editor",
            }) end, row, token)
            pauseCare(1, row, token)
            assert(data("team") == "Babies", "Bebek rolu sunucuda dogrulanmadi.")
        end)
        return
    end
    if data("roleplay_role") then notify("Aktif iş bitene kadar bakım bekliyor."); return end
    if autoPets and selectedItem() and not selectedWrapper() then
        if careScheduler.Count() > 0 then cancelCare(); return end
        api.equipSelected(); return
    end
    if stationMode and not stationInitialized then
        local loc = Interiors.get_current_location()
        if not careStation or not careStation.Parent or not loc or loc.interior ~= stationInterior then
            if careScheduler.Count() > 0 then cancelCare(); return end
            local token = careEpoch
            runAction(function()
                local row = {target = autoBaby and "baby" or "pet", unique = selected}
                careNavigate("housing", row, token)
                checkCare(row, token)
                createCareStation()
                row.returningStation=true;moveNear(careStation.Position, row, token)
            end)
            return
        end
    end
    if stationMode and careStation and careStation.Parent and locationId()==stationLocation then
        local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
        if careScheduler.Count() == 0 and #ailments()==0 and #ailments("baby")==0 and root and (root.Position - careStation.Position).Magnitude > 10 then
            local token = careEpoch
            runAction(function()
                moveNear(careStation.Position, {target = autoBaby and "baby" or "pet", unique = selected,returningStation=true}, token)
            end)
            return
        end
    end
    stationWaiting = {}
    local rows = {}
    if autoPets then for _, row in ipairs(ailments()) do table.insert(rows, row) end end
    if autoBaby then for _, row in ipairs(ailments("baby")) do table.insert(rows, row) end end
    local priority = {mystery = 0, sick = 1, dirty = 2, bored=2, camping=2, beach_party=2, party_zone=2, sleepy = 3, hungry = 4, thirsty = 4,
        toilet = 5, pet_me = 6, play = 10, walk = 9, ride = 8}
    table.sort(rows, function(a, b)
        local ar, br = (a.raw.rate or 0) > 0, (b.raw.rate or 0) > 0
        if ar ~= br then return ar end
        local ap, bp = priority[a.kind] or 7, priority[b.kind] or 7
        if ap ~= bp then return ap < bp end
        return a.order == b.order and a.target < b.target or a.order < b.order
    end)
    stopGuide()
    careScheduler.Tick(rows)
    careState = careScheduler.Snapshot()[1]
end
-- ClientData emits after replicated packets have been decoded. This avoids
-- interpreting raw packet fields or acknowledgements as task completion.
wakeCare = function()
    careDirty = true
    if not alive or carePumpQueued then return end
    carePumpQueued = true
    task.delay(0.12, function()
        carePumpQueued = false
        if not alive then return end
        local ok, err = pcall(tickCare)
        if not ok then lastError = tostring(err) end
        careDirty, lastCareTick = false, os.clock()
    end)
end
table.insert(connections, CD.DataChangedEvent:Connect(function(key)
    if key=="inventory" then observeFoodPurchases() end
    if key == "ailments_manager" or key == "inventory" or key == "team" or key == "char_wrapper" or
        key == "equip_manager" or key == "location" then wakeCare() end
end))
table.insert(connections, player.CharacterRemoving:Connect(function() cancelCare() end))

function api.setAutoPets(value)
    cancelCare(); stopGuide()
    autoPets, autoVenues, venueState = value == true, false, nil
    notify(autoPets and "Pet bakımı event'lerle otomatik." or "Pet bakımı kapalı.")
    wakeCare()
end
function api.setAutoBaby(value)
    cancelCare(); stopGuide()
    autoBaby, autoVenues, venueState = value == true, false, nil
    notify(autoBaby and "Bebek rolü ve görev otomasyonu açık." or "Bebek bakımı kapalı.")
    wakeCare()
end
function api.stopAll()
    autoPets, autoBaby, autoVenues, autoSwap = false, false, false, false
    venueState = nil
    cancelCare(); stopGuide()
    notify("Bütün otomasyonlar durduruldu.")
end
function api.setPaused(reason)
    local nextReason=type(reason)=="string" and reason or nil
    if pauseReason==nextReason then return end
    pauseReason=nextReason
    cancelCare();stopGuide();venueState=nil
    if not pauseReason then actionRetryAt=0;wakeCare() end
    notify(pauseReason or "Tur bitti · bakım kaldığı yerden devam ediyor.")
end
function api.setStationMode(value)
    cancelCare()
    stationMode = value == true
    stationWaiting = {}
    wakeCare()
    notify(stationMode and "Sabit BasePart bakımı açık." or "Konumlar arasında normal bakım açık.")
end
local function waitCareDrain()
    local deadline=os.clock()+25
    while careScheduler.Count()>0 and os.clock()<deadline do task.wait(0.1) end
    assert(careScheduler.Count()==0,"Önceki bakım sunucu yanıtını bekliyor; işlem bitince tekrar dene.")
    return alive
end
function api.setStationHere()
    cancelCare()
    return runAction(function()
        if not waitCareDrain() then return end
        createCareStation()
        stationMode = true
        notify("BasePart bakım noktası bulunduğun konuma yerleştirildi.")
        wakeCare()
    end)
end
function api.equipSelected()
    if careScheduler.Count() > 0 then cancelCare() end
    return runAction(function()
        if not waitCareDrain() then return end
        stopGuide(); equip(); notify("Seçilen pet takıldı.")
    end)
end
function api.navigate(destination)
    local entry=assert(travelLocations.byId[destination],"Bu konum kısayollarda tanımlı değil.")
    assert(not pauseReason and not MinigameForcedState.is_enabled(),"Mini oyun bitince konum değiştirebilirsin.")
    assert(not busy,"Önce mevcut işlemin bitmesini bekle.")
    api.stopAll()
    return runAction(function()
        if not waitCareDrain() then return end
        stopGuide();navigate(entry.destination)
        if entry.marker then
            local folder=workspace:FindFirstChild("StaticMap") and workspace.StaticMap:FindFirstChild("TeleportLocations")
            local target=folder and folder:FindFirstChild(entry.marker)
            local deadline=os.clock()+8
            while not target and alive and os.clock()<deadline do
                task.wait(0.1)
                folder=workspace:FindFirstChild("StaticMap") and workspace.StaticMap:FindFirstChild("TeleportLocations")
                target=folder and folder:FindFirstChild(entry.marker)
            end
            assert(alive and target and target:IsA("BasePart"),"Bu harita noktası şu anda yüklenmiş değil.")
            assert(not pauseReason and not MinigameForcedState.is_enabled(),"Mini oyun geçişi başladı.")
            local character=assert(player.Character,"Karakter hazır değil.")
            character:PivotTo(target.CFrame*CFrame.new(0,3,0))
            local root=character:FindFirstChild("HumanoidRootPart")
            if root then root.AssemblyLinearVelocity=Vector3.zero end
        end
        notify("Konum: "..entry.title)
    end)
end
function api.locations() return travelLocations end
function api.guide(key)
    api.stopAll()
    return runAction(function()
        stopGuide()
        equip()
        if not alive then return end
        local wrapper = selectedWrapper()
        local current
        for _, row in ipairs(ailments()) do if row.key == key then current = row end end
        assert(current, "Gorev artik aktif degil.")
        local instance = Ailment.new(player, current.raw, selected)
        activeGuide = instance.action
        notify("Oyunun görev rehberi açılıyor…")
        activeGuide:start(wrapper)
        if alive then notify("Görev rehberi: " .. (labels[current.kind] or current.kind)) end
    end)
end
function api.setAutoVenues(value)
    autoPets, autoBaby = false, false
    cancelCare()
    autoVenues = value == true
    venueState = nil
    retryAt = 0
    stopGuide()
    notify(autoVenues and "Okul / salon / pizza / kafe görevleri izleniyor." or "Konum otomasyonu kapalı.")
end
function api.setAutoSwap(value)
    autoSwap = value == true
    notify(autoSwap and "Yetişkin petten büyümemiş pete geçiş açık." or "Otomatik pet değişimi kapalı.")
end
function api.setPreferEggs(value)
    preferEggs=value==true
    petChoice.Reset();petHandover=nil
    wakeCare()
    notify(preferEggs and "Yumurtalar öncelikli; bitince rastgele petle devam eder." or "Yumurta tercihi kapalı.")
end
function api.setWaterBudget(value)
    local amount=tonumber(value)
    assert(amount and amount==amount and amount>=0 and amount<=1000,"Su bütçesi 0–1000 Bucks arasında olmalı.")
    waterBudget=math.floor(amount);wakeCare()
end
function api.isIdle() return not busy and actionPending==0 and careScheduler.Count()==0 end
function api.select(unique)
    assert(petInventory()[unique], "Bu pet envanterinde bulunamadi.")
    assert(not busy, "Once mevcut islemin bitmesini bekle.")
    stopGuide()
    cancelCare()
    selected = unique
    venueState = nil
    wakeCare()
end
function api.snapshot()
    rebuildPets()
    observeFoodPurchases()
    local rows = {}
    for _, row in ipairs(ailments()) do
        table.insert(rows, {key = row.key, kind = row.kind, progress = row.progress})
    end
    local babyRows = {}
    for _, row in ipairs(ailments("baby")) do
        table.insert(babyRows, {key = row.key, kind = row.kind, progress = row.progress})
    end
    local item = selectedItem()
    return {placeId = game.PlaceId, placeVersion = game.PlaceVersion, money = data("money"),
        moneyDelta = (data("money") or 0) - startMoney, petCount = #petList,
        selected = selected, petName = item and petName(item),
        age = item and item.properties and item.properties.age,
        equipped = selectedWrapper() ~= nil, location = locationId(), tasks = rows,
        autoVenues = autoVenues, autoSwap = autoSwap, busy = busy,actionPending=actionPending,
        preferEggs=preferEggs,eggCount=inventoryEggCount,petChoiceMode=petChoice.mode,petHandover=petHandover~=nil,
        autoPets = autoPets, autoBaby = autoBaby, babyTasks = babyRows, team = data("team"),
        careState = careScheduler.Snapshot()[1], careJobs = careScheduler.Snapshot(),
        activeCareJobs = careScheduler.Count(), peakCareJobs = careScheduler.peak, schedulerVersion = 8,
        paused=pauseReason~=nil,pauseReason=pauseReason,recoveries=careScheduler.recoveries,
        stationMode = stationMode, stationReady = careStation ~= nil and careStation.Parent ~= nil,
        stationLocation = stationLocation, stationWaiting = stationWaiting,
        careHistory = careHistory, waterSpent = waterSpent, waterBudget = waterBudget,
        waterReserved=reservedFoodBudget(),pendingFoodPurchases=select(2,reservedFoodBudget()),
        venueState = venueState, lastError = lastError, alive = alive,
        autoCandy = env.AdoptMeCandyRain and env.AdoptMeCandyRain.enabled or false,
        notice=api.notice}
end
function api.pets()
    rebuildPets()
    local rows={}
    for _,entry in ipairs(petList) do
        table.insert(rows,{unique=entry.unique,name=petName(entry.item),age=(entry.item.properties or {}).age or 0,isEgg=entry.isEgg})
    end
    return rows
end
function api.taskName(kind) return labels[kind] or kind end
function api.unload()
    if not alive then return end
    env.AdoptMeCarePrevious = {autoPets = autoPets, autoBaby = autoBaby, autoSwap = autoSwap,
        selected = selected, waterSpent = waterSpent,waterBudget=waterBudget,preferEggs=preferEggs}
    alive, autoVenues, autoSwap = false, false, false
    autoPets, autoBaby = false, false
    cancelCare()
    stopGuide()
    for _, connection in ipairs(connections) do connection:Disconnect() end
    for _, row in ipairs(taskRows) do row.connection:Disconnect() end
    if gui then gui:Destroy() end
    if careStation then careStation:Destroy(); careStation = nil end
    if env.AdoptMeCompanion == api then env.AdoptMeCompanion = nil end
end

