-- The flag is drawn with native UI geometry: no asset IDs or downloaded images.
local function drawFlag(parent, name, x, y, width, transparency, zIndex)
    local height = width * 8 / 11
    local flag = create("Frame", {Name = name, Position = UDim2.fromOffset(x, y),
        Size = UDim2.fromOffset(width, height), BackgroundColor3 = theme.white,
        BackgroundTransparency = transparency, BorderSizePixel = 0,
        Active = false, ZIndex = zIndex}, parent)
    for _, bandY in ipairs({height * 5 / 32, height * 22 / 32}) do
        create("Frame", {Name = "BlueBand", Position = UDim2.fromOffset(0, bandY),
            Size = UDim2.fromOffset(width, height * 5 / 32), BackgroundColor3 = theme.blue,
            BackgroundTransparency = transparency, BorderSizePixel = 0,
            Active = false, ZIndex = zIndex}, flag)
    end
    local center = Vector2.new(width / 2, height / 2)
    local radius, thickness = height * 0.22, math.max(2, height * 0.022)
    for _, initialAngle in ipairs({-90, 90}) do
        local vertices = {}
        for i = 0, 2 do
            local angle = math.rad(initialAngle + i * 120)
            vertices[i + 1] = center + Vector2.new(math.cos(angle), math.sin(angle)) * radius
        end
        for i = 1, 3 do
            local from, to = vertices[i], vertices[i % 3 + 1]
            local delta, middle = to - from, (from + to) / 2
            create("Frame", {Name = "StarEdge", AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromOffset(middle.X, middle.Y),
                Size = UDim2.fromOffset(delta.Magnitude + thickness / 2, thickness),
                Rotation = math.deg(math.atan2(delta.Y, delta.X)),
                BackgroundColor3 = theme.blue, BackgroundTransparency = transparency,
                BorderSizePixel = 0, Active = false, ZIndex = zIndex}, flag)
        end
    end
    return flag
end
