local function tickAutomation(rows)
    if pauseReason or MinigameForcedState.is_enabled() or os.clock()<actionRetryAt then return end
    if busy or os.clock() < retryAt then return end
    local item = selectedItem()
    if tickPetChoice() then return end
    item=selectedItem()
    if autoSwap and not preferEggs and item and (item.properties or {}).age == 6 then
        if careScheduler.Count() > 0 then cancelCare(); return end
        for _, entry in ipairs(petList) do
            if entry.unique ~= selected and ((entry.item.properties or {}).age or 6) < 6 then
                selected = entry.unique
                venueState = nil
                api.equipSelected()
                return
            end
        end
    end
    if not autoVenues then return end
    if data("roleplay_role") then notify("Aktif iş nedeniyle konum otomasyonu bekliyor."); return end
    if not item then notify("Önce bir pet seç."); return end
    if not selectedWrapper() then api.equipSelected(); retryAt = os.clock() + 12; return end
    if venueState then
        local current
        for _, row in ipairs(rows) do if row.key == venueState.key then current = row end end
        if not current then
            notify("Konum görevi sona erdi: " .. (labels[venueState.kind] or venueState.kind))
            venueState = nil
        elseif os.clock() - venueState.started > 95 then
            notify("Konum görevi takıldı; otomatik yeniden denenecek.")
            venueState=nil;retryAt=os.clock()+5
            return
        else
            return
        end
    end
    for _, row in ipairs(rows) do
        local destination = venues[row.kind]
        if destination and row.progress < 1 then
            venueState = {key = row.key, kind = row.kind, started = os.clock()}
            retryAt = os.clock() + 12
            runAction(function()
                stopGuide()
                navigate(destination)
                notify("Görevin sunucuda ilerlemesi bekleniyor: " .. (labels[row.kind] or row.kind))
            end)
            return
        end
    end
end
