function state.setEnabled(value)
    state.enabled=value==true
    if state.enabled then retryAt=0;errorStreak=0 end
    if not state.enabled then state.status="Kapalı" end
end
function state.setPaused(reason) state.pauseReason=type(reason)=="string" and reason or nil end
function state.stop() state.running=false;state.enabled=false;if gui then gui:Destroy() end end
if toggle then toggle.Activated:Connect(function()state.setEnabled(not state.enabled)end) end
local function step()
    local snapshot=CD.get_server(Players.LocalPlayer,"admin_abuse_manager")
    if type(snapshot)~="table" or type(snapshot.drops)~="table" then
        state.status="Şeker verisi hazırlanıyor";return
    end
    local candy=snapshot.drops.candy_2026 or {}
    assert(type(candy)=="table","Şeker verisi henüz hazır değil.")
    local now=os.clock()
    -- Drop IDs change throughout an AFK session; discard retired retry state.
    for id in pairs(cooldown) do if not candy[id] then cooldown[id]=nil;attempts[id]=nil end end
    if state.pending then
        local pending=state.pending
        local entry=candy[pending.unique]
        local count=entry and entry.num_drops or 0
        if count<pending.count then
            state.confirmed+=math.min(pending.count-count,1)
            state.pending=nil;attempts[pending.unique]=nil;cooldown[pending.unique]=now+0.3
        elseif now-pending.time>3 then
            state.failures+=1
            if (attempts[pending.unique] or 0)>=3 then
                -- Retry a rejected group after a rest, rather than blacklisting
                -- an otherwise valid server-advertised drop for the session.
                cooldown[pending.unique]=now+60;attempts[pending.unique]=nil
            else cooldown[pending.unique]=now+8 end
            state.pending=nil
        end
    end
    if not state.enabled then state.status="Kapalı";return end
    if state.pauseReason then state.status=state.pauseReason;return end
    local minigame=Manager.get("ghost_clusters")
    if minigame and minigame.is_participating then state.status="Ghost Gallery sırasında bekliyor";return end
    local loc=Interiors.get_current_location()
    local party=require(RS.new.modules.AdminAbuse).get_value("party_zone")
    local destination=party and party.destination_id or "MainMap"
    if not loc or loc.destination_id~=destination then state.status=destination.." konumunda bekliyor";return end
    if state.pending then state.status="Toplama sunucuda doğrulanıyor";return end
    local unique,entry
