            else errorStreak=0;state.error=nil end
        end
        if not state.running then break end
        if status then status.Text=state.status.." · Toplanan: "..state.confirmed end
        if toggle then toggle.Text=state.enabled and "Otomatik şeker: AÇIK (kapat)" or "Otomatik şeker: KAPALI (aç)" end
