local createWatch=function()
-- Temporary, read-only event observation. Requires an already running SimpleSpy.
local env = getgenv()
assert(env.SimpleSpy and type(env.SimpleSpy.GetRemoteFiredSignal) == "function", "SimpleSpy is not running")
if env.AdoptMeEventWatch and env.AdoptMeEventWatch.stop then env.AdoptMeEventWatch.stop("replaced") end
local RS, Players = game:GetService("ReplicatedStorage"), game:GetService("Players")
local load = require(RS.Fsys).load
local Router, CD = load("RouterClient"), load("ClientData")
local watch = {running = true, connections = {}, records = {}, counts = {}, seq = 0,
    deadlineUnix = DateTime.now().UnixTimestamp + 300, lastReportedSeq = 0, observed = {}, subscriptionErrors=0}
env.AdoptMeEventWatch = watch
local function summarize(value, depth)
    local kind = typeof(value)
    if kind == "string" then return value:sub(1,120) end
    if kind == "number" or kind == "boolean" or kind == "nil" then return value end
    if kind == "Instance" then return value.Name .. " (" .. value.ClassName .. ")" end
    if kind == "buffer" then return "buffer:" .. buffer.len(value) end
    if kind == "table" and depth > 0 then
        local out, count = {}, 0
        for key, item in pairs(value) do
            if type(key) == "string" or type(key) == "number" then
                out[tostring(key)] = summarize(item,depth-1); count += 1
                if count >= 10 then break end
            end
        end
        return out
    end
    return kind
end
function watch.stop(reason)
    if not watch.running then return end
    watch.running, watch.stopReason = false, reason or "stopped"
    for _,c in ipairs(watch.connections) do pcall(function() c:Disconnect() end) end
    watch.connections={};watch.observed={}
end
local motionLast = {}
local function record(direction,name,args)
    if not watch.running then return end
    if DateTime.now().UnixTimestamp >= watch.deadlineUnix then watch.stop("observation window ended"); return end
    local counter = direction .. ":" .. name
    watch.counts[counter] = (watch.counts[counter] or 0) + 1
    if name:find("GhostClustersNet",1,true) then
        if motionLast[counter] and os.clock() - motionLast[counter] < 2 then return end
        motionLast[counter] = os.clock()
    end
    local values = {}
    for i=1,math.min(args.n or #args,5) do values[i]=summarize(args[i],2) end
    watch.seq += 1
    table.insert(watch.records,{seq=watch.seq,direction=direction,name=name,args=values,time=os.clock()})
    if #watch.records > 256 then table.remove(watch.records,1) end
end
local function observe(remote,name,incoming)
    if not watch.running then return end
    if watch.observed[remote] then return end
    watch.observed[remote] = name
    if remote:IsA("RemoteEvent") or remote:IsA("RemoteFunction") then
        local connected,connection=pcall(function()
            return env.SimpleSpy:GetRemoteFiredSignal(remote):Connect(function(args)
                if type(args)=="table" then record("out",name,args) end
            end)
        end)
        if connected then table.insert(watch.connections,connection)
        else watch.subscriptionErrors+=1 end
    end
    if incoming and (remote:IsA("RemoteEvent") or remote:IsA("UnreliableRemoteEvent")) then
        table.insert(watch.connections,remote.OnClientEvent:Connect(function(...)
            record("in",name,table.pack(...))
        end))
    end
end
for _,name in ipairs({"MinigameAPI/MessageServer","MinigameAPI/MessageClient","MinigameAPI/AttemptJoin",
    "Halloween2026API/GetLeaderboardData","Halloween2026API/LeaderboardUpdated",
    "AdoptAPI/SendPassiveDoorEnter","LocationAPI/SetLocation","ToolAPI/Equip"}) do
    local ok,remote = pcall(Router.get,name)
    if ok and typeof(remote)=="Instance" then observe(remote,name,true) end
end
local net = RS:FindFirstChild("adoptme_new_net")
local function observeNew(remote)
    if remote.Name:find("Halloween2026",1,true) then observe(remote,remote.Name,true) end
end
if net then
    for _,remote in ipairs(net:GetChildren()) do observeNew(remote) end
    table.insert(watch.connections,net.ChildAdded:Connect(observeNew))
end
table.insert(watch.connections,CD.DataChangedEvent:Connect(function(key)
    if type(key)=="string" and (key:find("halloween_2026",1,true) or key:find("minigame",1,true)) then
        record("data",key,table.pack(CD.get_server(Players.LocalPlayer,key)))
    end
end))
task.spawn(function()
    while watch.running and DateTime.now().UnixTimestamp < watch.deadlineUnix do task.wait(1) end
    watch.stop("five-minute monitoring window ended")
end)
print("[AdoptMeEventWatch] SimpleSpy event monitoring ready")

return env.AdoptMeEventWatch
end
local createTrace=function()
-- Read-only subscriptions to SimpleSpy. No replay, blocking, or argument changes.
local env = getgenv()
assert(env.SimpleSpy and type(env.SimpleSpy.GetRemoteFiredSignal) == "function", "SimpleSpy must be running")
if env.AdoptMeSpyTrace then
    env.AdoptMeSpyTrace.running=false
    for _,c in ipairs(env.AdoptMeSpyTrace.connections or {}) do pcall(function()c:Disconnect()end) end
end
local trace = {running=true,connections = {}, records = {}, counts = {}}
env.AdoptMeSpyTrace = trace
local Router = require(game.ReplicatedStorage.Fsys).load("RouterClient")
for _,name in ipairs({"AdoptAPI/SendPassiveDoorEnter", "LocationAPI/SetLocation", "ToolAPI/Equip", "ToolAPI/Unequip",
    "HousingAPI/ActivateFurniture", "HousingAPI/ActivateInteriorFurniture", "PetAPI/ExitFurnitureUseStates",
    "AdoptAPI/ExitSeatStates", "PetObjectAPI/CreatePetObject", "PetAPI/ConsumeFoodObject", "ShopAPI/BuyItem",
    "PetAPI/ProgressPetMeAilment", "AilmentsAPI/ProgressPetMeAilment", "AilmentsAPI/ChooseMysteryAilment",
    "RoleplayAPI/AbandonRoleplayRole", "StateManagerAPI/CreateState"}) do
    local ok, remote = pcall(Router.get, name)
    if ok and typeof(remote) == "Instance" then
        local connected,connection=pcall(function()return env.SimpleSpy:GetRemoteFiredSignal(remote):Connect(function(args)
            if not trace.running or type(args)~="table" then return end
            trace.counts[name] = (trace.counts[name] or 0) + 1
            local summary = {}
            for i=1,math.min(args.n or #args,5) do
                local value, kind = args[i], typeof(args[i])
                summary[i] = (kind == "string" or kind == "number" or kind == "boolean") and tostring(value):sub(1,90) or kind
            end
            table.insert(trace.records, {name = name, args = summary, time = os.clock()})
            if #trace.records > 60 then table.remove(trace.records, 1) end
        end)end)
        if connected then table.insert(trace.connections,connection) end
    end
end
print("[AdoptMeSpy] Observing native task calls")

return env.AdoptMeSpyTrace
end
