local hub={running=true,ready=false,build=report.build,connections={},controls={},runtimeErrors={}}
local ui,care,ghost,candy,transfer,crypt,inventoryAutomation,window
local function uiContext() if setthreadidentity then pcall(setthreadidentity,8) end end
local function stopTrace()
    local trace=env.AdoptMeSpyTrace
    if trace then
        for _,connection in ipairs(trace.connections or {}) do pcall(function()connection:Disconnect()end) end
        trace.connections={};trace.running=false
    end
end
local function stopWatch()
    local watch=env.AdoptMeEventWatch
    if watch and watch.stop then watch.stop("menu stopped") end
end
local function safely(fn)
    local ok,err=pcall(fn)
    if not ok then hub.error=tostring(err) end
end
function hub.stopAll()
    if hub.autoJoin then safely(function()hub.autoJoin.setEnabled(false)end) end
    if care then safely(care.stopAll) end
    if ghost then safely(function()ghost.setEnabled(false)end) end
    if candy then safely(function()candy.setEnabled(false)end) end
    if transfer then safely(function()transfer.setEnabled(false)end) end
    if crypt then safely(function()crypt.setEnabled(false)end) end
    if inventoryAutomation then safely(inventoryAutomation.stopAll)end
    if hub.afk then safely(function()hub.afk.setEnabled(false)end) end
    safely(stopWatch);safely(stopTrace)
end
local function clean()
    if not hub.running then return end
    hub.running=false;hub.ready=false
    hub.stopAll()
    if hub.autoJoin then safely(hub.autoJoin.stop) end
    if care then safely(care.unload) end
    if ghost then safely(ghost.stop) end
    if candy then safely(candy.stop) end
    if transfer then safely(transfer.stop) end
    if crypt then safely(crypt.stop) end
    if inventoryAutomation then safely(inventoryAutomation.stop)end
    if hub.afk then safely(hub.afk.stop) end
    for _,connection in ipairs(hub.connections) do pcall(function()connection:Disconnect()end) end
    if env.BulbulComeback==hub then env.BulbulComeback=nil end
end
function hub.unload()
    clean()
    uiContext()
    if ui and not ui.Unloaded then
        if ui.CreatedWindow then ui:Destroy() else
            ui.Utilities.Creator.Disconnect()
            ui.GUI:Destroy()
            ui.Unloaded=true
        end
    end
end
function hub.snapshot()
    return {title="bülbül comeback",build=hub.build,ready=hub.ready,care=care and care.snapshot(),transfer=transfer and transfer.snapshot(),
        afk=hub.afk and hub.afk.snapshot(),runtimeErrors=hub.runtimeErrors,
        crypt=crypt and crypt.snapshot(),
        inventory=inventoryAutomation and inventoryAutomation.snapshot(),
        ghost=ghost and {enabled=ghost.enabled,status=ghost.status,score=ghost.score,error=ghost.error},
        candy=candy and {enabled=candy.enabled,status=candy.status,confirmed=candy.confirmed,error=candy.error},
        cycle=hub.autoJoin and {enabled=hub.autoJoin.enabled,phase=hub.autoJoin.phase,status=hub.autoJoin.status,
            paused=hub.autoJoin.paused,error=hub.autoJoin.error,joins=hub.autoJoin.joins,resumes=hub.autoJoin.resumes}}
end
local function action(fn)
    return function(...)
        if not hub.running then return end
        uiContext()
        local ok,err=pcall(fn,...)
        if not ok then
            hub.error=tostring(err)
            if hub.running and ui and not ui.Unloaded then
                ui:Notify{Title="bülbül comeback",Content=hub.error:sub(1,180),Duration=4}
            end
        end
    end
end
local ok,err=xpcall(function()
    -- Load the UI before stopping existing automation.
    report.stage="UI yükleniyor"
    ui=createFluent()
    assert(env.BulbulComebackLoad==report,"Bu yükleme daha yeni bir sürümle değiştirildi.")
    local oldCycle=env.BulbulComeback and env.BulbulComeback.autoJoin
    if oldCycle and oldCycle.isIdle then
        oldCycle.setEnabled(false)
        local deadline=os.clock()+25
        while not oldCycle.isIdle() and os.clock()<deadline do task.wait(0.1)end
        assert(env.BulbulComebackLoad==report,"Bu yükleme daha yeni bir sürümle değiştirildi.")
        assert(oldCycle.isIdle(),"Önceki Ghost Gallery geçişi sunucu yanıtını bekliyor; yanıt geldikten sonra tekrar yükle.")
    end
    local oldTransfer=env.BulbulComeback and env.BulbulComeback.transfer or env.BulbulBucksActive
    local oldInventory=env.BulbulInventoryActive
    if oldInventory then
        oldInventory.stopAll()
        local deadline=os.clock()+30
        while oldInventory.busy and os.clock()<deadline do task.wait(0.1)end
        assert(not oldInventory.busy,"Önceki anahtar/iksir işlemi henüz bitmedi; yanıt geldikten sonra yeniden yükle.")
        oldInventory.stop()
    end
    if oldTransfer then
        oldTransfer.setEnabled(false)
        local deadline=os.clock()+25
        while oldTransfer.busy and os.clock()<deadline do task.wait(0.1)end
        assert(env.BulbulComebackLoad==report,"Bu yükleme daha yeni bir sürümle değiştirildi.")
        assert(not oldTransfer.busy,"Önceki ödeme isteği henüz bitmedi; yanıt geldikten sonra yeniden yükle.")
        oldTransfer.stop()
    end
    if previousCare then
        report.stage="Önceki bakım temizleniyor"
        previousCare.stopAll()
        local deadline=os.clock()+25
        local function previousIdle()
            if previousCare.isIdle then return previousCare.isIdle() end
            local state=previousCare.snapshot();return state.activeCareJobs==0 and not state.busy
        end
        while not previousIdle() and os.clock()<deadline do task.wait(0.1) end
        assert(env.BulbulComebackLoad==report,"Bu yükleme daha yeni bir sürümle değiştirildi.")
        if not previousIdle() then
            previousCare.setAutoPets(previous.autoPets);previousCare.setAutoBaby(previous.autoBaby)
            error("Önceki bakım işlemi sunucu yanıtını bekliyor; tekrar yükle.")
        end
    end
    local oldHub=env.BulbulComeback
    assert(env.BulbulComebackLoad==report,"Bu yükleme daha yeni bir sürümle değiştirildi.")
    report.stage="Önceki menü kaldırılıyor"
    if oldHub and oldHub.unload then oldHub.unload() end
    assert(env.BulbulComebackLoad==report,"Bu yükleme daha yeni bir sürümle değiştirildi.")
    env.BulbulComebackHost=hub
    report.stage="Bakım modülü yükleniyor"
    care=createCare()
    transfer=createTransfer(care,hub);hub.transfer=transfer
    candy=env.AdoptMeCandyRain
    ghost=createGhost()
    crypt=createCrypt(hub);hub.crypt=crypt
    crypt.setEnabled(previousCrypt)
    inventoryAutomation=createInventory(care,hub);hub.inventoryAutomation=inventoryAutomation
    if env.BulbulComebackHost==hub then env.BulbulComebackHost=nil end
    hub.care,hub.ghost,hub.candy=care,ghost,candy
    assert(env.BulbulComebackLoad==report,"Bu yükleme daha yeni bir sürümle değiştirildi.")
    env.BulbulComeback=hub
    if previous.selected then
        for _,pet in ipairs(care.pets()) do if pet.unique==previous.selected then care.select(previous.selected);break end end
    end
    care.setPreferEggs(previous.preferEggs==true)
    if previous.waterBudget then care.setWaterBudget(previous.waterBudget) end
    care.setStationMode(previous.stationMode~=false)
    if previous.autoVenues then care.setAutoVenues(true) else
        care.setAutoPets(previous.autoPets==true);care.setAutoBaby(previous.autoBaby==true)
    end
    care.setAutoSwap(previous.autoSwap==true)
    ghost.setEnabled(previousGhost);candy.setEnabled(previousCandy)

    report.stage="Tur koordinatörü yükleniyor"
    local nativeLoad=require(game:GetService("ReplicatedStorage").Fsys).load
    local Manager,Interiors,CD=nativeLoad("MinigameClientManager"),nativeLoad("InteriorsM"),nativeLoad("ClientData")
    local Forced,Clock=nativeLoad("MinigameForcedState"),nativeLoad("LiveOpsTime")
    local virtualUser=game:GetService("VirtualUser")
    hub.afk=newAfkGuard({Now=os.clock,Spawn=task.spawn,Wait=task.wait,
        Bind=function(callback)return game:GetService("Players").LocalPlayer.Idled:Connect(callback)end,
        Press=function()
            uiContext();virtualUser:CaptureController()
            virtualUser:Button2Down(Vector2.zero,workspace.CurrentCamera and workspace.CurrentCamera.CFrame or CFrame.identity)
        end,
        Release=function()
            uiContext();virtualUser:Button2Up(Vector2.zero,workspace.CurrentCamera and workspace.CurrentCamera.CFrame or CFrame.identity)
        end},previousAfk)
    local cyclePauseReason
    local function manager() return Manager.get("ghost_clusters") end
    local function location() return Interiors.get_current_location() end
    local function joinCollider()
        local m,loc=manager(),location()
        if not m or not loc or loc.destination_id~=m.join_zone_destination_id then return end
        local found,model=pcall(m.get_join_zone_model,loc.interior)
        return found and model and model:FindFirstChild("Collider") or nil
    end
    local function leaveQueue()
        local m=manager()
        if not m or m.is_participating then return end
        local collider=joinCollider()
        local character=game:GetService("Players").LocalPlayer.Character
        if collider and character then
            -- Cylinder X is its height; leave across the radius instead of upward.
            local position=(collider.CFrame*CFrame.new(0,0,collider.Size.Z/2+6)).Position
            local pivot=character:GetPivot()
            character:PivotTo(CFrame.new(position)*pivot.Rotation)
            local root=character:FindFirstChild("HumanoidRootPart")
            if root then root.AssemblyLinearVelocity=Vector3.zero end
        end
    end
    local function inJoinZone()
        local collider=joinCollider()
        local character=game:GetService("Players").LocalPlayer.Character
        local root=character and character:FindFirstChild("HumanoidRootPart")
        if not collider or not root then return false end
        -- Same normalized cylinder test as the game's MinigameJoinZone.
        local p=collider.CFrame:PointToObjectSpace(root.Position)/collider.Size
        return math.abs(p.X)<=0.5 and p.Y*p.Y+p.Z*p.Z<=0.25
    end
    hub.autoJoin=newGhostCycle({Now=Clock.now,Read=function()
        local m=manager();local loc=location();local cycle=m and CD.get(m.cycle_timestamp_key)
        local active=m and m.is_participating==true
        return {active=active,transition=Forced.is_enabled() or (not active and m and m.instanced_minigame~=nil) or
                (loc and loc.destination_id:find("ManorMinigameInterior",1,true)~=nil),
            timestamp=cycle and cycle.timestamp,queued=m and m.is_queued,inJoinZone=inJoinZone(),
            loading=m and m.minigame_state:get("players_loading"),canInvite=Forced.can_receive_invites()}
    end,Ready=function() local s=care.snapshot();return not transfer.busy and not inventoryAutomation.busy and not s.busy and s.activeCareJobs==0 end,
        Pause=function(reason)cyclePauseReason=reason;transfer.setPaused(reason);care.setPaused(reason);candy.setPaused(reason)end,
        Resume=function()
            transfer.setPaused(nil)
            if care.snapshot().pauseReason==cyclePauseReason then care.setPaused(nil) end
            candy.setPaused(nil);cyclePauseReason=nil
        end,LeaveQueue=leaveQueue,
        Prepare=function(done,valid)
            task.spawn(function()
                local moved,moveError=xpcall(function()
                    assert(hub.running and valid(),"Katılım iptal edildi.")
                    local m=assert(manager(),"Ghost Gallery henüz yüklenmedi.")
                    local loc=location()
                    if not loc or loc.destination_id~=m.join_zone_destination_id then
                        local UI=nativeLoad("UIManager")
                        local dialog=UI.apps.DialogApp
                        local matching=false
                        if dialog.visible then
                            for _,label in ipairs(dialog.instance:GetDescendants()) do
                                if label:IsA("TextLabel") and label.Text:find("Ghost Gallery",1,true) and label.Text:find("Teleport",1,true) then matching=true;break end
                            end
                        end
                        local accepted=false
                        if matching and firesignal then
                            for _,label in ipairs(dialog.instance:GetDescendants()) do
                                if (label:IsA("TextLabel") or label:IsA("TextButton")) and label.Text=="Yes" then
                                    local button=label
                                    while button and not button:IsA("GuiButton") do button=button.Parent end
                                    if button and button.Visible then
                                        -- Native DepthButton requires a down event before accepting a click.
                                        firesignal(button.MouseButton1Down)
                                        firesignal(button.MouseButton1Click)
                                        firesignal(button.MouseButton1Up)
                                        accepted=true;break
                                    end
                                end
                            end
                        end
                        if accepted then
                            local deadline=os.clock()+25
                            repeat task.wait(0.1);loc=location() until not valid() or os.clock()>deadline or loc and loc.destination_id==m.join_zone_destination_id
                        else
                            local spawn=workspace.StaticMap.TeleportLocations:FindFirstChild(m.minigame_id)
                            Interiors.enter_smooth(m.join_zone_destination_id,"MainDoor",{spawn_cframe=spawn and spawn.CFrame})
                        end
                    end
                    assert(hub.running and valid(),"Katılım iptal edildi.")
                    local collider=joinCollider();local deadline=os.clock()+8
                    while not collider and valid() and os.clock()<deadline do task.wait(0.1);collider=joinCollider() end
                    assert(collider,"Katılım alanı yüklenmedi.")
                    local character=assert(game:GetService("Players").LocalPlayer.Character,"Karakter hazır değil.")
                    character:PivotTo(collider.CFrame)
                    local root=character:FindFirstChild("HumanoidRootPart")
                    if root then root.AssemblyLinearVelocity=Vector3.zero end
                    deadline=os.clock()+3
                    while not m.is_queued and not m.is_participating and valid() and os.clock()<deadline do task.wait(0.1) end
                    assert(m.is_queued or m.is_participating,"Oyun katılım sırasını doğrulamadı.")
                end,debug.traceback)
                done(moved,moveError)
            end)
        end},previousAutoJoin)

