    local function flag(parent,name,size,position,opacity)
        local frame=Instance.new("Frame")
        frame.Name,frame.Size,frame.Position=name,size,position
        frame.BackgroundColor3=Color3.new(1,1,1);frame.BackgroundTransparency=1
        frame.BorderSizePixel=0;frame.Active=false;frame.ClipsDescendants=true;frame.Parent=parent
        for _,y in ipairs({5/32,22/32}) do
            local band=Instance.new("Frame")
            band.Name="BlueBand";band.Size=UDim2.fromScale(1,5/32);band.Position=UDim2.fromScale(0,y)
            band.BackgroundColor3=blue;band.BackgroundTransparency=opacity;band.BorderSizePixel=0;band.Parent=frame
        end
        local edges={}
        for _=1,6 do
            local edge=Instance.new("Frame");edge.Name="StarEdge";edge.AnchorPoint=Vector2.new(0.5,0.5)
            edge.BackgroundColor3=blue;edge.BackgroundTransparency=opacity;edge.BorderSizePixel=0;edge.Parent=frame
            table.insert(edges,edge)
        end
        local function fit()
            local s=frame.AbsoluteSize;local h=math.min(s.Y,s.X*8/11)
            local center=Vector2.new(s.X/2,s.Y/2);local radius=h*0.22;local thickness=math.max(1,h*0.018)
            local index=0
            for _,initial in ipairs({-90,90}) do
                local vertices={}
                for i=0,2 do local a=math.rad(initial+i*120);vertices[i+1]=center+Vector2.new(math.cos(a),math.sin(a))*radius end
                for i=1,3 do
                    index+=1;local delta=vertices[i%3+1]-vertices[i];local middle=(vertices[i%3+1]+vertices[i])/2
                    edges[index].Position=UDim2.fromOffset(middle.X,middle.Y)
                    edges[index].Size=UDim2.fromOffset(delta.Magnitude+thickness/2,thickness)
                    edges[index].Rotation=math.deg(math.atan2(delta.Y,delta.X))
                end
            end
        end
        table.insert(hub.connections,frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit));fit()
        return frame
    end
