    local function subtabs(parent,id,definitions)
        local group={pages={},buttons={}}
        local row=Instance.new("Frame")
        row.Name=id.."Subtabs";row.Size=UDim2.new(1,0,0,36)
        row.BackgroundTransparency=1;row.LayoutOrder=1;row.Parent=parent.Container
        local layout=Instance.new("UIListLayout")
        layout.FillDirection=Enum.FillDirection.Horizontal;layout.Padding=UDim.new(0,6)
        layout.SortOrder=Enum.SortOrder.LayoutOrder;layout.Parent=row
        function group.select(key)
            uiContext()
            assert(group.pages[key],"Alt sekme bulunamadı.")
            group.selected=key
            for name,page in pairs(group.pages) do
                page.root.Visible=name==key
                local button=group.buttons[name]
                button.BackgroundColor3=name==key and blue or Color3.fromRGB(232,240,255)
                button.TextColor3=name==key and Color3.new(1,1,1) or ink
            end
            parent.ScrollFrame.CanvasPosition=Vector2.zero
        end
        for index,definition in ipairs(definitions) do
            local key,title=definition[1],definition[2]
            local page=parent:CreateSection(title)
            local root=page.Container.Parent
            root.Name=id.."_"..key;root.LayoutOrder=2;root.Visible=false
            group.pages[key]={tab=page,root=root}
            local button=Instance.new("TextButton")
            button.Name=key;button.Size=UDim2.new(1/#definitions,-6*(#definitions-1)/#definitions,1,0)
            button.LayoutOrder=index;button.Text=title;button.TextSize=12
            button.Font=Enum.Font.GothamMedium;button.BorderSizePixel=0;button.Parent=row
            local corner=Instance.new("UICorner");corner.CornerRadius=UDim.new(0,7);corner.Parent=button
            group.buttons[key]=button
            table.insert(hub.connections,button.MouseButton1Click:Connect(action(function()group.select(key)end)))
        end
        group.select(definitions[1][1])
        hub.subtabs[id]=group
        return group
    end
