    local function update()
        uiContext()
        local snap=care.snapshot()
        if waterBudgetInput.Value~=tostring(snap.waterBudget) then waterBudgetInput:SetValue(tostring(snap.waterBudget)) end
        setText(petStatus,string.format("%s · yaş %s/6\n%d pet · Bucks %s%s",snap.petName or "Pet yok",snap.age or "?",snap.petCount,snap.money or "?",
            snap.preferEggs and string.format("\nYumurta: %d · %s",snap.eggCount,snap.petChoiceMode=="egg" and "Yumurta açılıyor" or "Rastgele pet / bekleniyor") or ""))
        petChoices=care.pets();local signature={}
        for _,pet in ipairs(petChoices) do table.insert(signature,pet.unique..":"..pet.name..":"..pet.age) end
        signature=table.concat(signature,"|")
        if signature~=petFingerprint then
            petFingerprint=signature;petByLabel={};petLabels={}
            local values={}
            for index,pet in ipairs(petChoices) do
                local label=string.format("%d · %s · %s/6",index,pet.name,pet.age)
                table.insert(values,label);petByLabel[label]=pet.unique;petLabels[pet.unique]=label
            end
            petSelect:SetValues(values)
        end
        local selectedLabel=petLabels[snap.selected]
        if selectedLabel and petSelect.Value~=selectedLabel then petSelect:SetValue(selectedLabel) end
        local actual={AutoPets=snap.autoPets,AutoBaby=snap.autoBaby,AutoSwap=snap.autoSwap,PreferEggs=snap.preferEggs,AntiAfk=hub.afk.enabled,StationMode=snap.stationMode,
            AutoVenues=snap.autoVenues,GhostEnabled=ghost.enabled,GhostAutoJoin=hub.autoJoin.enabled,CandyEnabled=candy.enabled,TransferEnabled=transfer.enabled,CryptESP=crypt.enabled,
            CryptAuto=inventoryAutomation.cryptEnabled,AutoAgePotion=inventoryAutomation.ageEnabled,TransferRemoteOnly=transfer.remoteOnly}
        for id,value in pairs(actual) do local control=hub.controls[id];if control.Value~=value then control:SetValue(value) end end
        local lines={string.format("%d aktif / en fazla 6 paralel iş",snap.activeCareJobs)}
        local active={}
        for _,job in ipairs(snap.careJobs) do active[job.target..":"..job.key]=job end
        for _,list in ipairs({{rows=snap.tasks,name="Pet"},{rows=snap.babyTasks,name="Bebek"}}) do
            for _,row in ipairs(list.rows) do
                local job=active[(list.name=="Pet" and "pet" or "baby")..":"..row.key]
                table.insert(lines,list.name.." · "..care.taskName(row.kind).." · %"..math.floor(row.progress*100).." · "..
                    (job and (job.mode=="observe" and "İlerliyor" or job.stage) or "Sırada"))
            end
        end
        setText(jobs,table.concat(lines,"\n"));setText(notice,(snap.pauseReason or snap.lastError or snap.notice or "Hazır")..string.format("\nSu alımı: %d + %d ayrılan / %d Bucks",snap.waterSpent,snap.waterReserved or 0,snap.waterBudget))
        local values,newMap,signature={},{},{}
        for _,row in ipairs(snap.tasks) do
            local label=care.taskName(row.kind).." · "..row.key
            table.insert(values,label);newMap[label]=row.key;table.insert(signature,label)
        end
        signature=table.concat(signature,"|")
        if signature~=guideFingerprint then guideFingerprint=signature;guideMap=newMap;guide:SetValues(values) end
        setText(ghostStatus,string.format("%s\n%s\nPuan: %s · Işınlanma: %s\nKalkış: %s%s",hub.autoJoin.status,ghost.status,ghost.score,ghost.teleports or 0,ghost.recoveryJumps or 0,ghost.error and "\n"..ghost.error or ""))
        setText(candyStatus,string.format("%s\nToplanan: %s · İstek: %s%s",candy.status,candy.confirmed,candy.sent,candy.error and "\n"..candy.error or ""))
        local cryptSnap=crypt.snapshot()
        setText(cryptStatus,cryptSnap.status.."\nİşaretlenen merdivenli mezar: "..cryptSnap.matched..(cryptSnap.error and "\n"..cryptSnap.error or ""))
        local work=inventoryAutomation.snapshot()
        local workText=work.status..string.format("\nAçılan mezar: %d · Son ödül: %d · Kullanılan iksir: %d",work.opened,work.rewards,work.potions)
        setText(inventoryStatus,workText);setText(ageStatus,workText)
        setText(locationStatus,snap.location)
        setText(eventLocationStatus,snap.location)
        local players=game:GetService("Players"):GetPlayers()
        table.sort(players,function(a,b)return a.Name:lower()<b.Name:lower()end)
        local labels,mapping,inverse,playerSignature={},{},{},{}
        for _,p in ipairs(players)do
            if p~=game:GetService("Players").LocalPlayer then
                local label=p.Name.." · "..p.DisplayName
                table.insert(labels,label);mapping[label]=p.UserId;inverse[p.UserId]=label
                table.insert(playerSignature,tostring(p.UserId)..":"..label)
            end
        end
        playerSignature=table.concat(playerSignature,"|")
        syncingPlayers=true
        if playerSignature~=playerFingerprint then
            playerFingerprint=playerSignature;playerByLabel=mapping;playerLabels=inverse;playerSelect:SetValues(labels)
        end
        local targetLabel=playerLabels[transfer.targetId]
        if targetLabel and playerSelect.Value~=targetLabel then playerSelect:SetValue(targetLabel)end
        syncingPlayers=false
        local pay=transfer.snapshot()
        for id,field in pairs({TransferAmount="amount",TransferBatch="batchCount",TransferInterval="interval",TransferLimit="limit",TransferReserve="reserve"})do
            local control=hub.controls[id];local value=tostring(transfer[field])
            if control.Value~=value then control:SetValue(value)end
        end
        setText(transferStatus,string.format("%s\nHedef: %s\nDoğrulanan: %d Bucks · Limitten ayrılan: %d\nDeneme: %d · Sonraki ödeme: %d sn%s",
            pay.status,targetLabel or "Seçilmedi / oyuncu ayrıldı",pay.confirmed,pay.reserved,pay.attempts,pay.nextIn,pay.error and "\n"..pay.error or ""))
        local watch,trace=env.AdoptMeEventWatch,env.AdoptMeSpyTrace
        local afk=hub.afk.snapshot();local errors={}
        for name,failure in pairs(hub.runtimeErrors)do table.insert(errors,name..": "..failure)end
        setText(afkStatus,string.format("AFK: %s · %d giriş\n%s",afk.enabled and "Açık" or "Kapalı",afk.count,
            afk.lastError or #errors>0 and table.concat(errors,"\n") or "Sistem çalışıyor"))
        setText(traceStatus,string.format("SimpleSpy: %s\nEtkinlik kaydı: %s · %d kayıt\nPet kaydı: %s · %d kayıt",env.SimpleSpy and "Açık" or "Kapalı",watch and watch.running and "Açık" or "Kapalı",watch and #watch.records or 0,trace and trace.running and "Açık" or "Kapalı",trace and #trace.records or 0))
    end
    update()
    hub.ready=true;report.ready=true;report.stage="Hazır"
    task.spawn(function()
        local function checked(name,fn)
            local succeeded,failure=pcall(fn)
            if succeeded then hub.runtimeErrors[name]=nil;return end
            local message=tostring(failure)
            if hub.runtimeErrors[name]~=message then warn("[bülbül comeback / "..name.."] "..message) end
            hub.runtimeErrors[name]=message;hub.error=message;report.runtimeError=message
        end
        while hub.running do
            task.wait(0.5)
            if not hub.running then break end
            checked("Ghost Gallery",hub.autoJoin.step)
            checked("Bucks",transfer.step)
            checked("Menü",update)
        end
    end)
end,debug.traceback)
if env.BulbulComebackHost==hub then env.BulbulComebackHost=nil end
report.inProgress=false
report.ok,report.error=ok,not ok and tostring(err) or nil
if not ok then hub.unload();warn("[bülbül comeback] "..tostring(err)) end
return hub
